# Round 54 -- part28 rows 42-77; 32 items
BATCH={
  (28, 42): {
   "topic": "placentaAccretaSpectrum",
   "lead": "\u0646\u0641\u0648\u0630 \u062c\u0641\u062a \u0628\u0647 \u062c\u062f\u0627\u0631 \u0645\u062b\u0627\u0646\u0647 \u062d\u06cc\u0646 \u0633\u0632\u0627\u0631\u06cc\u0646 \u062f\u0631 \u0633\u0627\u0628\u0642\u0647\u0654 \u062f\u0648 \u0633\u0632\u0627\u0631\u06cc\u0646: \u062c\u0641\u062a Percreta (\u0639\u0645\u06cc\u0642\u200c\u062a\u0631\u06cc\u0646 \u0646\u0648\u0639 \u0633\u0646\u062f\u0631\u0645 \u0622\u06a9\u0631\u06cc\u062a\u0627).",
   "interpretation": "\u062f\u0631 \u0637\u06cc\u0641 \u0686\u0633\u0628\u0646\u062f\u06af\u06cc \u062c\u0641\u062a\u060c \u0622\u06a9\u0631\u06cc\u062a\u0627 \u0686\u0633\u0628\u0646\u062f\u06af\u06cc \u0628\u0647 \u0645\u06cc\u0648\u0645\u062a\u0631 \u0628\u062f\u0648\u0646 \u0646\u0641\u0648\u0630 \u0627\u0633\u062a\u060c \u0627\u06cc\u0646\u06a9\u0631\u06cc\u062a\u0627 \u0646\u0641\u0648\u0630 \u0628\u0647 \u062f\u0627\u062e\u0644 \u0645\u06cc\u0648\u0645\u062a\u0631 \u0648 \u067e\u0631\u06a9\u0631\u06cc\u062a\u0627 \u0646\u0641\u0648\u0630 \u0627\u0632 \u0633\u0631\u0648\u0632\u0627 \u06af\u0630\u0634\u062a\u0647 \u0648 \u0628\u0647 \u0627\u0631\u06af\u0627\u0646\u200c\u0647\u0627\u06cc \u0645\u062c\u0627\u0648\u0631 \u0645\u062b\u0644 \u0645\u062b\u0627\u0646\u0647 \u0627\u0633\u062a\u061b \u06cc\u0627\u0641\u062a\u0647\u0654 \u062d\u06cc\u0646 \u0639\u0645\u0644 (\u0646\u0641\u0648\u0630 \u0628\u0647 \u0645\u062b\u0627\u0646\u0647) \u0645\u0633\u062a\u0642\u06cc\u0645\u0627\u064b \u0628\u0647 \u0645\u0631\u062d\u0644\u0647\u0654 \u067e\u0631\u06a9\u0631\u06cc\u062a\u0627 \u0627\u0634\u0627\u0631\u0647 \u062f\u0627\u0631\u062f \u0648 \u0639\u0627\u0645\u0644 \u0632\u0645\u06cc\u0646\u0647\u200c\u0627\u06cc \u0627\u0635\u0644\u06cc (\u0686\u0646\u062f \u0633\u0632\u0627\u0631\u06cc\u0646 \u0642\u0628\u0644\u06cc) \u0627\u06cc\u0646 \u0637\u06cc\u0641 \u0631\u0627 \u0628\u0631\u0627\u06cc \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc\u200c\u0647\u0627\u06cc \u0634\u062f\u06cc\u062f \u062d\u06cc\u0646 \u062a\u062e\u0644\u06cc\u0647\u0654 \u062c\u0641\u062a \u0622\u0645\u0627\u062f\u0647 \u0645\u06cc\u200c\u06a9\u0646\u062f.",
   "reasons": ["\u0622\u06a9\u0631\u06cc\u062a\u0627 \u0641\u0642\u0637 \u0686\u0633\u0628\u0646\u062f\u06af\u06cc \u0633\u0637\u062d\u06cc \u062c\u0641\u062a \u0628\u0647 \u0645\u06cc\u0648\u0645\u062a\u0631 \u0627\u0633\u062a \u0648 \u0628\u0647 \u0645\u062b\u0627\u0646\u0647 \u0646\u0645\u06cc\u200c\u0631\u0633\u062f.", "\u0627\u06cc\u0646\u06a9\u0631\u06cc\u062a\u0627 \u0628\u0647 \u0639\u0645\u0642 \u0645\u06cc\u0648\u0645\u062a\u0631 \u0646\u0641\u0648\u0630 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648\u0644\u06cc \u0627\u0632 \u0633\u0631\u0648\u0632\u0627 \u0639\u0628\u0648\u0631 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u0646\u0641\u0648\u0630 \u0641\u0631\u0627\u062a\u0631 \u0627\u0632 \u0633\u0631\u0648\u0632\u0627 \u0628\u0647 \u0645\u062b\u0627\u0646\u0647 \u062a\u0639\u0631\u06cc\u0641 \u067e\u0631\u06a9\u0631\u06cc\u062a\u0627 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0646\u0641\u0648\u0630 \u0648\u06cc\u0644\u0627\u0645\u0646\u062a\u0648\u0633 \u0627\u062a\u0635\u0627\u0644 \u0648\u06cc\u0644\u0627\u0645\u0646\u062a\u0648\u0633 \u0628\u0646\u062f \u0646\u0627\u0641 \u0627\u0633\u062a \u0646\u0647 \u0686\u0633\u0628\u0646\u062f\u06af\u06cc \u062c\u0641\u062a."],
  },
  (28, 43): {
   "topic": "pphProstaglandinSide",
   "lead": "\u062a\u0628 \u0648 \u062a\u0647\u0648\u0639 \u0648 \u0627\u0633\u062a\u0641\u0631\u0627\u063a \u067e\u0633 \u0627\u0632 \u062a\u0632\u0631\u06cc\u0642 PGF2a (\u06a9\u0627\u0631\u0628\u0648\u067e\u0631\u0648\u0633\u062a) \u062f\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0645\u0647\u0627\u0631\u0634\u062f\u0647: \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u062a\u0641\u0633\u06cc\u0631 \u0627\u06cc\u0646 \u062a\u0631\u06a9\u06cc\u0628\u060c \u0639\u0627\u0631\u0636\u0647\u0654 \u062f\u0627\u0631\u0648\u06cc \u067e\u0631\u0648\u0633\u062a\u0627\u06af\u0644\u0627\u0646\u062f\u06cc\u0646 \u0627\u0633\u062a.",
   "interpretation": "\u06a9\u0627\u0631\u0628\u0648\u067e\u0631\u0648\u0633\u062a (\u067e\u0631\u0648\u0633\u062a\u0627\u06af\u0644\u0627\u0646\u062f\u06cc\u0646 F2 \u0622\u0644\u0641\u0627) \u0645\u0648\u062c\u0628 \u0627\u0646\u0642\u0628\u0627\u0636 \u0642\u0648\u06cc \u0631\u062d\u0645 \u0628\u0631\u0627\u06cc \u06a9\u0646\u062a\u0631\u0644 \u0622\u062a\u0648\u0646\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f \u0648\u0644\u06cc \u0639\u0648\u0627\u0631\u0636 \u062f\u0633\u062a\u06af\u0627\u0647 \u06af\u0648\u0627\u0631\u0634 (\u062a\u0647\u0648\u0639\u060c \u0627\u0633\u062a\u0641\u0631\u0627\u063a\u060c \u0627\u0633\u0647\u0627\u0644) \u0648 \u062a\u0628 \u0639\u0627\u0628\u0631 \u0627\u0632 \u0639\u0648\u0627\u0631\u0636 \u0634\u0646\u0627\u062e\u062a\u0647\u200c\u0634\u062f\u0647\u0654 \u0627\u0648\u0633\u062a \u06a9\u0647 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u0627 \u062f\u0631\u0645\u0627\u0646 \u062d\u0645\u0627\u06cc\u062a\u06cc (\u0636\u062f\u062a\u0647\u0648\u0639\u060c \u0645\u0627\u06cc\u0639\u0627\u062a) \u06a9\u0646\u062a\u0631\u0644 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646\u0627\u0631\u06cc\u0648 \u0639\u0644\u0627\u0626\u0645 \u0628\u0639\u062f \u0627\u0632 \u062a\u062c\u0648\u06cc\u0632 \u062f\u0627\u0631\u0648 \u0638\u0627\u0647\u0631 \u0634\u062f\u0647 \u0648 \u0634\u0648\u0627\u0647\u062f\u06cc \u0628\u0631\u0627\u06cc \u0639\u0641\u0648\u0646\u062a (\u0645\u0627\u0646\u0646\u062f \u062a\u0631\u0634\u062d \u0628\u062f\u0628\u0648) \u06cc\u0627 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 (\u0641\u0634\u0627\u0631 \u0628\u0627\u0644\u0627/\u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc/\u0639\u0644\u0627\u06cc\u0645 \u0639\u0635\u0628\u06cc) \u0645\u0637\u0631\u062d \u0646\u06cc\u0633\u062a\u061b \u0628\u0627 \u0641\u0634\u0627\u0631 \u06f1\u06f3\u06f0/\u06f7\u06f0 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062f\u0631 \u062d\u062f \u0645\u0637\u0631\u062d \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0628\u0627 \u0641\u0634\u0627\u0631 \u06f1\u06f3\u06f0/\u06f7\u06f0 \u0648 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u06cc\u0645 \u0639\u0635\u0628\u06cc/\u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc \u0627\u06cc\u0646\u200c\u062c\u0627 \u0645\u0637\u0631\u062d \u0646\u06cc\u0633\u062a.", "\u0645\u062a\u0631\u0698\u06cc\u0646 \u0628\u06cc\u0634\u200c\u062a\u0631 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0641\u0634\u0627\u0631 \u0627\u06cc\u062c\u0627\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f \u0646\u0647 \u062a\u0628 \u0648 \u0639\u0648\u0627\u0631\u0636 \u06af\u0648\u0627\u0631\u0634\u06cc \u0628\u0627\u0631\u0632.", "\u062a\u0647\u0648\u0639\u060c \u0627\u0633\u062a\u0641\u0631\u0627\u063a \u0648 \u062a\u0628 \u0639\u0627\u0628\u0631 \u0639\u0648\u0627\u0631\u0636 \u0634\u0627\u06cc\u0639 \u067e\u0631\u0648\u0633\u062a\u0627\u06af\u0644\u0627\u0646\u062f\u06cc\u0646 \u0627\u0633\u062a \u0648 \u062f\u0631\u0645\u0627\u0646 \u062d\u0645\u0627\u06cc\u062a\u06cc \u06a9\u0627\u0641\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0628\u062f\u0648\u0646 \u062a\u0631\u0634\u062d \u0628\u062f\u0628\u0648 \u06cc\u0627 \u062a\u0646\u062f\u0631\u0646\u0633\u060c \u067e\u0631\u0648\u0633\u0647\u0654 \u0639\u0641\u0648\u0646\u06cc \u062f\u0631 \u0635\u062f\u0631 \u0646\u06cc\u0633\u062a."],
  },
  (28, 44): {
   "topic": "preeclampsiaTwinsDelivery",
   "lead": "\u062f\u0648\u0642\u0644\u0648\u06cc\u06cc \u06f3\u06f7 \u0647\u0641\u062a\u0647 \u0628\u0627 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc (\u06f1\u06f4\u06f0/\u06f9\u06f0 + \u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc \u06f1+): \u062a\u0631\u0645 \u0631\u0633\u06cc\u062f\u0647 \u0648 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0634\u0627\u06cc\u0633\u062a\u0647 \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u067e\u0633 \u0627\u0632 \u06f3\u06f7 \u0647\u0641\u062a\u0647\u060c \u0645\u062f\u06cc\u0631\u06cc\u062a \u0642\u0637\u0639\u06cc \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a \u0686\u0648\u0646 \u0646\u06af\u0647\u200c\u062f\u0627\u0634\u062a\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0647\u0645 \u062f\u0631 \u062f\u0648\u0642\u0644\u0648\u06cc\u06cc \u0648 \u0647\u0645 \u062f\u0631 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0628\u0647 \u062e\u0637\u0631 \u0645\u0627\u062f\u0631/\u062c\u0646\u06cc\u0646 \u0627\u0633\u062a \u0648 \u062f\u0631 \u062d\u0627\u0644\u062a \u0645\u0648\u062c\u0648\u062f \u0647\u06cc\u0686 \u0639\u0644\u062a \u0645\u0624\u06cc\u062f \u0628\u0631\u0627\u06cc \u062a\u0639\u0644\u0644 \u0646\u06cc\u0633\u062a\u061b \u06a9\u0648\u0631\u062a\u0648\u0646 \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u062f\u06cc\u06af\u0631 \u062a\u063a\u06cc\u06cc\u0631\u062f\u0647\u0646\u062f\u0647\u0654 \u062a\u0635\u0645\u06cc\u0645 \u0646\u06cc\u0633\u062a \u0648 \u00ab\u067e\u0627\u06cc\u0634 \u062a\u0627 \u06f3\u06f8 \u0647\u0641\u062a\u0647 \u06cc\u0627 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u0647\u0641\u062a\u06af\u06cc\u00bb \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u0628\u06cc\u0645\u0627\u0631 \u0628\u062f\u0648\u0646 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0627\u0633\u062a\u060c \u0646\u0647 \u0628\u06cc\u0645\u0627\u0631 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062a\u0631\u0645.",
   "reasons": ["\u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062a\u0631\u0645 \u062f\u0648\u0642\u0644\u0648\u06cc\u06cc \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u062f\u0627\u0645\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u0627 \u06f3\u06f8 \u0647\u0641\u062a\u0647 \u062f\u0631 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062e\u0637\u0631 \u0631\u0627 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f.", "\u06a9\u0648\u0631\u062a\u0648\u0646 \u062f\u0631 \u06f3\u06f7 \u0647\u0641\u062a\u0647 \u0628\u0631\u0627\u06cc \u0628\u0644\u0648\u063a \u0631\u06cc\u0647 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a \u0648 \u062e\u062a\u0645 \u0631\u0627 \u0628\u0647 \u062a\u0623\u062e\u06cc\u0631 \u0645\u06cc\u200c\u0627\u0646\u062f\u0627\u0632\u062f.", "\u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u0647\u0641\u062a\u06af\u06cc \u062f\u0631 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062a\u0631\u0645 \u062c\u0627\u06cc \u062e\u062a\u0645 \u0631\u0627 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u062f."],
  },
  (28, 45): {
   "topic": "migrainePregSafest",
   "lead": "\u062f\u0631 \u062d\u0645\u0644\u0647\u0654 \u0645\u06cc\u06af\u0631\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06f3\u06f4 \u0647\u0641\u062a\u0647\u060c \u06a9\u0645\u200c\u0639\u0627\u0631\u0636\u0647\u200c\u062a\u0631\u06cc\u0646 \u06af\u0632\u06cc\u0646\u0647\u0654 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a \u0627\u0633\u062a\u0627\u0645\u06cc\u0646\u0648\u0641\u0646-\u06a9\u062f\u0626\u06cc\u0646 (\u062a\u0631\u06a9\u06cc\u0628 \u0627\u0633\u062a\u0627\u0645\u06cc\u0646\u0648\u0641\u0646 \u0628\u0627 \u062f\u0648\u0632 \u067e\u0627\u06cc\u06cc\u0646 \u0645\u062e\u062f\u0631) \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631\u0648\u0633 \u062d\u0645\u0644\u0647\u200c\u0627\u06cc \u0645\u06cc\u06af\u0631\u0646 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627\u06cc\u062f \u0628\u0627 \u062d\u062f\u0627\u0642\u0644 \u0627\u062b\u0631 \u0628\u0631 \u062c\u0646\u06cc\u0646 \u0627\u0646\u062a\u062e\u0627\u0628 \u0634\u0648\u0646\u062f: \u0627\u06cc\u0628\u0648\u067e\u0631\u0648\u0641\u0646 \u0648 \u0627\u06cc\u0646\u062f\u0648\u0645\u062a\u0627\u0633\u06cc\u0646 (\u062f\u0627\u0631\u0648\u0647\u0627\u06cc \u0636\u062f\u0627\u0644\u062a\u0647\u0627\u0628 \u063a\u06cc\u0631\u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f\u06cc) \u062f\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0633\u0648\u0645 \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u0628\u0633\u062a\u0646 \u062f\u0627\u06a9\u062a\u0648\u0633 \u0622\u0631\u062a\u0631\u06cc\u0648\u0632\u0648\u0633 \u0648 \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0645\u0645\u0646\u0648\u0639 \u06cc\u0627 \u0628\u0633\u06cc\u0627\u0631 \u0645\u062d\u062f\u0648\u062f\u0646\u062f \u0648 \u0627\u0631\u06af\u0648\u062a\u0627\u0645\u06cc\u0646 \u0645\u0645\u0646\u0648\u0639 \u0645\u0637\u0644\u0642 \u0627\u0633\u062a\u061b \u062f\u0631 \u0628\u06cc\u0646 \u0627\u06cc\u0646 \u0686\u0647\u0627\u0631 \u06af\u0632\u06cc\u0646\u0647\u060c \u0627\u0633\u062a\u0627\u0645\u06cc\u0646\u0648\u0641\u0646-\u06a9\u062f\u0626\u06cc\u0646 \u0628\u0647\u200c\u06a9\u0627\u0631 \u0631\u0641\u062a\u0646\u0650 \u0645\u0648\u0642\u062a\u06cc \u0648 \u0628\u0627 \u062f\u0648\u0632 \u06a9\u0648\u062a\u0627\u0647 \u0646\u0633\u0628\u062a \u0628\u0647 \u06af\u0632\u06cc\u0646\u0647\u200c\u0647\u0627\u06cc \u062f\u06cc\u06af\u0631 \u0627\u062b\u0631 \u062c\u0646\u06cc\u0646\u06cc \u06a9\u0645\u062a\u0631\u06cc \u062f\u0627\u0631\u062f \u0648 \u062f\u0631 \u0631\u0627\u0647\u0646\u0645\u0627\u06cc \u0628\u0627\u0644\u06cc\u0646\u06cc \u0647\u0645\u06cc\u0646 \u062a\u0648\u0635\u06cc\u0647 \u0627\u0633\u062a.",
   "reasons": ["\u0627\u06cc\u0628\u0648\u067e\u0631\u0648\u0641\u0646 \u062f\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0633\u0648\u0645 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0627\u062b\u0631 \u0628\u0631 \u062f\u0627\u06a9\u062a\u0648\u0633 \u0648 \u0645\u0627\u06cc\u0639 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u0645\u062d\u062f\u0648\u062f \u0627\u0633\u062a.", "\u0627\u0633\u062a\u0627\u0645\u06cc\u0646\u0648\u0641\u0646-\u06a9\u062f\u0626\u06cc\u0646 \u0628\u0627 \u06a9\u0645\u200c\u062a\u0631\u06cc\u0646 \u0627\u062b\u0631 \u062c\u0646\u06cc\u0646\u06cc \u062f\u0631 \u0645\u06cc\u0627\u0646 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u06cc\u0646\u062f\u0648\u0645\u062a\u0627\u0633\u06cc\u0646 \u062f\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0633\u0648\u0645 \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a (\u0628\u0633\u062a\u0646 \u062f\u0627\u06a9\u062a\u0648\u0633).", "\u0627\u0631\u06af\u0648\u062a\u0627\u0645\u06cc\u0646 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0627\u062b\u0631 \u0627\u0646\u0642\u0628\u0627\u0636\u200c\u062f\u0647\u0646\u062f\u06af\u06cc \u0631\u062d\u0645\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639 \u0645\u0637\u0644\u0642 \u0627\u0633\u062a."],
  },
  (28, 46): {
   "topic": "prematureOvarianInsufficiency",
   "lead": "\u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u062b\u0627\u0646\u0648\u06cc\u0647 \u0628\u0627 \u0627\u0633\u062a\u0631\u0627\u062f\u06cc\u0648\u0644 \u067e\u0627\u06cc\u06cc\u0646 \u0648 FSH=\u06f3\u06f5 \u0648 \u0639\u062f\u0645 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632-\u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646: \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654 \u062a\u062e\u0645\u062f\u0627\u0646 (POI).",
   "interpretation": "\u0627\u0641\u0632\u0627\u06cc\u0634 FSH (\u0628\u0627\u0644\u0627\u062a\u0631 \u0627\u0632 \u06f2\u06f5-\u06f4\u06f0) \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u06a9\u0627\u0647\u0634 \u0627\u0633\u062a\u0631\u0627\u062f\u06cc\u0648\u0644 \u06cc\u0639\u0646\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 \u0628\u0647 \u062a\u062d\u0631\u06cc\u06a9 \u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e\u06cc\u0646\u06cc \u067e\u0627\u0633\u062e \u0646\u0645\u06cc\u200c\u062f\u0647\u062f (\u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654/\u0632\u0648\u062f\u0631\u0633) \u0648 \u0646\u0628\u0648\u062f \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0646\u0634\u0627\u0646\u0647\u0654 \u0641\u0627\u0631\u063a \u0646\u0628\u0648\u062f\u0646 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0645\u0646\u0627\u0633\u0628 \u0628\u0631\u0627\u06cc \u0622\u0645\u0627\u062f\u0647\u200c\u0633\u0627\u0632\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0627\u0633\u062a\u061b \u0622\u0634\u0631\u0645\u0646 \u0628\u0627 FSH \u0637\u0628\u06cc\u0639\u06cc \u0645\u06cc\u200c\u0622\u06cc\u062f (\u0628\u0644\u0648\u063a \u0637\u0628\u06cc\u0639\u06cc \u0627\u0633\u062a\u0631\u0648\u0698\u0646\u06cc)\u060c PCOS \u0628\u0627 FSH \u0637\u0628\u06cc\u0639\u06cc \u06cc\u0627 \u067e\u0627\u06cc\u06cc\u0646 \u0648 \u0627\u0633\u062a\u0631\u0627\u062f\u06cc\u0648\u0644 \u0637\u0628\u06cc\u0639\u06cc \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a \u0648 \u0627\u062e\u062a\u0644\u0627\u0644 \u0639\u0645\u0644\u06a9\u0631\u062f \u0647\u06cc\u067e\u0648\u062a\u0627\u0644\u0627\u0645\u0648\u0633-\u0647\u06cc\u067e\u0648\u0641\u06cc\u0632 FSH \u067e\u0627\u06cc\u06cc\u0646 \u0645\u06cc\u200c\u062f\u0647\u062f \u0646\u0647 \u06f3\u06f5.",
   "reasons": ["\u0622\u0634\u0631\u0645\u0646 \u0628\u0627 \u0641\u0642\u062f\u0627\u0646 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0627\u0645\u0627 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0648 FSH \u0637\u0628\u06cc\u0639\u06cc \u0645\u06cc\u200c\u0622\u06cc\u062f \u0648 \u0645\u062a\u0646 \u0633\u0627\u0628\u0642\u0647\u0654 \u06a9\u0648\u0631\u062a\u0627\u0698 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u062f.", "\u0627\u0633\u062a\u0631\u0627\u062f\u06cc\u0648\u0644 \u067e\u0627\u06cc\u06cc\u0646 + FSH \u0628\u0627\u0644\u0627 \u0642\u0627\u0639\u062f\u0647\u0654 \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "PCOS \u0628\u0627 \u0627\u0633\u062a\u0631\u0627\u062f\u06cc\u0648\u0644 \u0637\u0628\u06cc\u0639\u06cc \u0648 FSH \u0637\u0628\u06cc\u0639\u06cc/\u067e\u0627\u06cc\u06cc\u0646 \u0645\u06cc\u200c\u0622\u06cc\u062f.", "\u0627\u062e\u062a\u0644\u0627\u0644 \u0647\u06cc\u067e\u0648\u062a\u0627\u0644\u0627\u0645\u0648\u0633-\u0647\u06cc\u067e\u0648\u0641\u06cc\u0632 \u0628\u0627 FSH \u067e\u0627\u06cc\u06cc\u0646 \u0648 LH \u067e\u0627\u06cc\u06cc\u0646 \u0645\u06cc\u200c\u0622\u06cc\u062f."],
  },
  (28, 47): {
   "topic": "earlyPregSerialHcg",
   "lead": "\u062a\u0623\u062e\u06cc\u0631 \u067e\u0631\u06cc\u0648\u062f + \u062f\u0631\u062f \u0632\u06cc\u0631 \u0634\u06a9\u0645 \u0648 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u062e\u0641\u06cc\u0641 \u0628\u0627 \u0639\u0644\u0627\u0626\u0645 \u062d\u06cc\u0627\u062a\u06cc \u067e\u0627\u06cc\u062f\u0627\u0631 \u0648 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0645\u0628\u0647\u0645: BHCG \u0633\u0631\u06cc\u0627\u0644\u06cc \u06f4\u06f8 \u0633\u0627\u0639\u062a \u0628\u0639\u062f.",
   "interpretation": "\u062a\u0634\u062e\u06cc\u0635 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u0645\u062d\u0644 \u0646\u0627\u0645\u0639\u0644\u0648\u0645 \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631 \u067e\u0627\u06cc\u062f\u0627\u0631 \u0628\u0627 \u0647\u0631 \u062f\u0648 \u0627\u062d\u062a\u0645\u0627\u0644 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0637\u0628\u06cc\u0639\u06cc \u0627\u0648\u0644\u06cc\u0647 \u0648 EP \u0646\u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0628\u0627 \u06cc\u06a9 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u0633\u062a\u0647 \u0634\u0648\u062f\u061b \u0627\u0628\u0632\u0627\u0631 \u0627\u0648\u0644\u06cc\u0647\u0654 \u0642\u0648\u06cc\u060c \u0631\u0648\u0646\u062f BHCG \u062f\u0631 \u06f4\u06f8 \u0633\u0627\u0639\u062a \u0627\u0633\u062a: \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u0633\u0627\u0644\u0645 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u062d\u062f\u0627\u0642\u0644 ~\u06f5\u06f0-\u06f6\u06f3\u066a \u0635\u0639\u0648\u062f \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0646\u0628\u0648\u062f \u0631\u0648\u0646\u062f \u0641\u0632\u0627\u06cc\u0646\u062f\u0647\u0654 \u0645\u0648\u0631\u062f \u0627\u0646\u062a\u0638\u0627\u0631 \u0628\u0631\u0627\u06cc EP \u0647\u0634\u062f\u0627\u0631 \u0627\u0633\u062a\u061b \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0647\u0641\u062a\u0647\u0654 \u0628\u0639\u062f \u0627\u06af\u0631 BHCG \u0646\u0627\u062d\u06cc\u0647\u0654 \u062a\u0641\u06a9\u06cc\u06a9 \u0631\u0627 \u0631\u062f \u06a9\u0646\u062f \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f \u0646\u0647 \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u0642\u062f\u0645 \u0627\u0648\u0644\u061b \u06a9\u0648\u0631\u062a\u0627\u0698 \u062a\u0634\u062e\u06cc\u0635\u06cc \u062a\u0647\u0627\u062c\u0645\u06cc \u0627\u0633\u062a \u0648 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u062c\u0627\u06cc\u06af\u0627\u0647 \u067e\u06cc\u0634\u06af\u06cc\u0631\u06cc \u0646\u062f\u0627\u0631\u062f.",
   "reasons": ["\u062a\u06cc\u062a\u0631\u0627\u0698 \u0645\u062c\u062f\u062f BHCG \u0686\u0647\u0644\u200c\u0648\u0647\u0634\u062a \u0633\u0627\u0639\u062a \u0628\u0639\u062f \u06af\u0627\u0645 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0627\u0648\u0644 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u06cc\u06a9 \u0647\u0641\u062a\u0647 \u0628\u0639\u062f \u0641\u0642\u0637 \u062f\u0631 \u0635\u0648\u0631\u062a \u0639\u0628\u0648\u0631 BHCG \u0627\u0632 \u0622\u0633\u062a\u0627\u0646\u0647\u0654 \u062a\u0634\u062e\u06cc\u0635 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u06a9\u0648\u0631\u062a\u0627\u0698 \u062a\u0634\u062e\u06cc\u0635\u06cc \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631 \u067e\u0627\u06cc\u062f\u0627\u0631 \u0628\u062f\u0648\u0646 \u062a\u0623\u06cc\u06cc\u062f \u0639\u062f\u0645\u200c\u0642\u0637\u0639\u06cc\u062a \u0628\u062f\u0646 \u062f\u0631\u0633\u062a \u0646\u06cc\u0633\u062a.", "\u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0628\u0631\u0627\u06cc \u062c\u0644\u0648\u06af\u06cc\u0631\u06cc \u0627\u0632 \u0633\u0642\u0637 \u062f\u0631 \u0627\u06cc\u0646 \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u0634\u0646\u0627\u0633\u06cc \u0645\u0624\u06cc\u062f \u0646\u06cc\u0633\u062a."],
  },
  (28, 48): {
   "topic": "solidOvarianMassYoung",
   "lead": "\u062a\u0648\u062f\u0647\u0654 \u062a\u0648\u067e\u0631 (\u0633\u0648\u0644\u06cc\u062f) \u062a\u062e\u0645\u062f\u0627\u0646 \u062d\u062a\u06cc \u062f\u0631 \u0632\u0646\u0627\u0646 \u062c\u0648\u0627\u0646: \u062a\u0627 \u0631\u0648\u0634\u0646 \u0646\u0634\u062f\u0646 \u0645\u0627\u0647\u06cc\u062a\u060c \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u062c\u0631\u0627\u062d\u06cc \u0644\u0627\u0632\u0645 \u0627\u0633\u062a \u0648 \u062f\u0631 \u0627\u06cc\u0646 \u06a9\u0644\u06cc\u062f \u0644\u0627\u067e\u0627\u0631\u0648\u062a\u0648\u0645\u06cc \u0627\u0646\u062a\u062e\u0627\u0628 \u0627\u0633\u062a.",
   "interpretation": "\u06a9\u06cc\u0633\u062a\u200c\u0647\u0627\u06cc \u0633\u0627\u062f\u0647 \u0639\u0645\u0644\u06cc\u0627\u062a\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 \u062f\u0631 \u0632\u0646\u0627\u0646 \u062c\u0648\u0627\u0646 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u0627 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc\u06a9 \u0645\u062f\u06cc\u0631\u06cc\u062a \u0645\u06cc\u200c\u0634\u0648\u0646\u062f\u060c \u0627\u0645\u0627 \u062a\u0648\u062f\u0647\u0654 \u00ab\u062a\u0648\u067e\u0631/\u0633\u0648\u0644\u06cc\u062f\u00bb \u0647\u0631 \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u0627\u06cc \u06a9\u0647 \u0628\u0627\u0634\u062f \u0627\u0632 \u0645\u0646\u0638\u0631 \u0627\u062d\u062a\u0645\u0627\u0644 \u062a\u0648\u0645\u0648\u0631\u0647\u0627\u06cc \u0633\u0644\u0648\u0644 \u062c\u0646\u06cc\u0646\u06cc/\u0627\u0633\u062a\u0631\u0648\u0645\u0627\u06cc\u06cc \u06cc\u0627 \u0622\u062f\u0646\u0648\u0645\u06cc\u0648\u0632 \u0627\u0647\u0645\u06cc\u062a \u062f\u0627\u0631\u062f \u0648 \u0635\u0631\u0641 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u06cc\u0627 \u062a\u062c\u0648\u06cc\u0632 \u0642\u0631\u0635 \u0636\u062f\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a\u061b \u0628\u06cc\u0648\u067e\u0633\u06cc \u0647\u062f\u0627\u06cc\u062a\u200c\u0634\u062f\u0647 \u0628\u0627 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0631 \u062a\u0648\u062f\u0647\u0654 \u0633\u0648\u0644\u06cc\u062f \u062a\u062e\u0645\u062f\u0627\u0646\u06cc \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u062e\u0637\u0631 \u067e\u062e\u0634 \u0628\u0630\u0631 \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u06cc\u0646 \u067e\u0631\u0633\u0634 \u0644\u0627\u067e\u0627\u0631\u0648\u062a\u0648\u0645\u06cc \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc/\u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0627\u0633\u062a.",
   "reasons": ["\u0628\u06cc\u0648\u067e\u0633\u06cc \u0628\u0627 \u06af\u0627\u06cc\u062f \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0631 \u062a\u0648\u062f\u0647\u0654 \u062a\u062e\u0645\u062f\u0627\u0646 \u0628\u0647\u200c\u0639\u0644\u062a \u062e\u0637\u0631 \u067e\u062e\u0634 \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0642\u0631\u0635 \u0636\u062f\u0628\u0627\u0631\u062f\u0627\u0631\u06cc+\u067e\u06cc\u06af\u06cc\u0631\u06cc \u0628\u0631\u0627\u06cc \u062a\u0648\u062f\u0647\u0654 \u0633\u0648\u0644\u06cc\u062f \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.", "\u062a\u06a9\u0631\u0627\u0631 \u0635\u0631\u0641 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0648 \u0645\u0627\u0647 \u0628\u0639\u062f \u062f\u0631 \u062a\u0648\u062f\u0647\u0654 \u0633\u0648\u0644\u06cc\u062f \u062a\u0635\u0645\u06cc\u0645 \u0631\u0627 \u0628\u0647 \u062a\u0623\u062e\u06cc\u0631 \u0645\u06cc\u200c\u0627\u0646\u062f\u0627\u0632\u062f.", "\u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u062c\u0631\u0627\u062d\u06cc (\u0644\u0627\u067e\u0627\u0631\u0648\u062a\u0648\u0645\u06cc) \u062f\u0631 \u062a\u0648\u062f\u0647\u0654 \u0633\u0648\u0644\u06cc\u062f \u062a\u062e\u0645\u062f\u0627\u0646 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 49): {
   "topic": "postMolarFollow",
   "lead": "\u067e\u0633 \u0627\u0632 \u062a\u062e\u0644\u06cc\u0647\u0654 \u0645\u0648\u0644\u060c \u062a\u0648\u0635\u06cc\u0647\u0654 \u06a9\u0644\u0627\u0633\u06cc\u06a9: \u0627\u062c\u0627\u0632\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06f6 \u0645\u0627\u0647 \u067e\u0633 \u0627\u0632 \u0645\u0646\u0641\u06cc \u0634\u062f\u0646 BHCG \u0633\u0631\u0645 (\u0628\u0627 \u06a9\u0646\u062a\u0631\u0644 \u0647\u0641\u062a\u06af\u06cc \u062a\u0627 \u0645\u0646\u0641\u06cc\u060c \u0633\u067e\u0633 \u0645\u0627\u0647\u0627\u0646\u0647 \u062f\u0631 \u0628\u0627\u0632\u0647\u0654 \u067e\u0627\u06cc\u0634).",
   "interpretation": "\u067e\u0633 \u0627\u0632 \u0645\u0648\u0644 \u06a9\u0627\u0645\u0644/\u062c\u0632\u0626\u06cc\u060c \u0645\u0647\u0645\u200c\u062a\u0631\u06cc\u0646 \u0645\u0627\u0646\u0639 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0632\u0648\u062f\u0647\u0646\u06af\u0627\u0645\u060c \u067e\u0646\u0647\u0627\u0646 \u0645\u0627\u0646\u062f\u0646 \u0639\u0648\u062f \u0628\u0647 \u0634\u06a9\u0644 GTN \u0627\u0633\u062a \u0686\u0648\u0646 BHCG \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062c\u062f\u06cc\u062f \u0628\u0627 BHCG \u0639\u0648\u062f \u0627\u0634\u062a\u0628\u0627\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0631\u0627\u0647\u0646\u0645\u0627\u06cc \u0642\u062f\u06cc\u0645/\u0645\u062a\u0639\u0627\u0631\u0641 \u0627\u06cc\u0631\u0627\u0646 \u00ab\u06f6 \u0645\u0627\u0647 \u067e\u0633 \u0627\u0632 \u0645\u0646\u0641\u06cc \u0634\u062f\u0646 BHCG\u00bb \u0627\u0633\u062a \u067e\u0633 \u0627\u0632 \u0622\u0646 \u06a9\u0647 \u067e\u0627\u06cc\u0634 \u0647\u0641\u062a\u06af\u06cc \u062a\u0627 \u0645\u0646\u0641\u06cc \u0648 \u0633\u067e\u0633 \u0645\u0627\u0647\u0627\u0646\u0647 \u0627\u062f\u0627\u0645\u0647\u200c\u062f\u0627\u0631 \u0627\u0633\u062a. \u067e\u06cc\u0634\u06af\u06cc\u0631\u06cc \u0627\u0632 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (\u0645\u062b\u0644\u0627\u064b \u06f6 \u0645\u0627\u0647 \u0627\u0632 \u0632\u0645\u0627\u0646 \u06a9\u0648\u0631\u062a\u0627\u0698 \u0628\u062f\u0648\u0646 \u0627\u062a\u06a9\u0627 \u0628\u0647 \u0645\u0646\u0641\u06cc \u0634\u062f\u0646) \u0645\u0628\u0646\u0627\u06cc \u062f\u0631\u0633\u062a\u06cc \u0646\u062f\u0627\u0631\u062f \u0648 \u06cc\u06a9 \u0633\u0627\u0644 \u067e\u0633 \u0627\u0632 \u0645\u0646\u0641\u06cc \u0634\u062f\u0646 \u062f\u0631 \u0627\u06a9\u062b\u0631 \u0631\u0627\u0647\u0646\u0645\u0627\u0647\u0627 \u0645\u062d\u0627\u0641\u0638\u0647\u200c\u06a9\u0627\u0631\u0627\u0646\u0647 \u0627\u0633\u062a.",
   "reasons": ["\u06f6 \u0645\u0627\u0647 \u067e\u0633 \u0627\u0632 \u06a9\u0648\u0631\u062a\u0627\u0698 \u0628\u062f\u0648\u0646 \u062a\u0648\u062c\u0647 \u0628\u0647 \u0646\u062a\u06cc\u062c\u0647\u0654 BHCG \u0645\u0628\u0646\u0627\u06cc \u062f\u0631\u0633\u062a\u06cc \u0646\u06cc\u0633\u062a.", "\u06f6 \u0645\u0627\u0647 \u067e\u0633 \u0627\u0632 \u0645\u0646\u0641\u06cc \u0634\u062f\u0646 BHCG \u062a\u0648\u0635\u06cc\u0647\u0654 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06cc\u06a9 \u0633\u0627\u0644 \u067e\u0633 \u0627\u0632 \u06a9\u0648\u0631\u062a\u0627\u0698 \u0628\u062f\u0648\u0646 \u067e\u0627\u06cc\u0647\u0654 BHCG \u0645\u0639\u06cc\u0627\u0631 \u0646\u06cc\u0633\u062a.", "\u06cc\u06a9 \u0633\u0627\u0644 \u067e\u0633 \u0627\u0632 \u0645\u0646\u0641\u06cc \u0634\u062f\u0646 BHCG \u0645\u062d\u0627\u0641\u0638\u0647\u200c\u06a9\u0627\u0631\u0627\u0646\u0647\u200c\u062a\u0631 \u0627\u0632 \u0645\u062a\u0646 \u0627\u06cc\u0646 \u06a9\u0644\u06cc\u062f \u0627\u0633\u062a."],
  },
  (28, 51): {
   "topic": "pcosFutureComplications",
   "lead": "PCOS \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u060c \u062f\u06cc\u0627\u0628\u062a \u0646\u0648\u0639 \u062f\u0648 \u0648 \u0628\u06cc\u0645\u0627\u0631\u06cc \u0642\u0644\u0628\u06cc\u200c\u0639\u0631\u0648\u0642\u06cc \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f\u061b \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u06a9\u0644\u06cc\u0648\u06cc \u062c\u0632\u0621 \u0639\u0648\u0627\u0631\u0636 \u0645\u0648\u0631\u062f\u0627\u0646\u062a\u0638\u0627\u0631 \u0622\u0646 \u0646\u06cc\u0633\u062a.",
   "interpretation": "\u0633\u0646\u062f\u0631\u0645 \u062a\u062e\u0645\u062f\u0627\u0646 \u067e\u0644\u06cc\u200c\u06a9\u06cc\u0633\u062a\u06cc\u06a9 \u0628\u0627 \u0622\u0646\u0648\u0648\u0644\u0627\u0633\u06cc\u0648\u0646 \u0645\u0632\u0645\u0646 \u0648 \u0645\u0642\u0627\u0648\u0645\u062a \u0627\u0646\u0633\u0648\u0644\u06cc\u0646\u06cc \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a \u0648 \u0628\u06cc\u0645\u0627\u0631 \u0631\u0627 \u062f\u0631 \u0628\u0631\u0627\u0628\u0631 \u062f\u06cc\u0627\u0628\u062a \u0646\u0648\u0639 \u06f2\u060c \u0633\u0646\u062f\u0631\u0645 \u0645\u062a\u0627\u0628\u0648\u0644\u06cc\u06a9 \u0648 \u0628\u06cc\u0645\u0627\u0631\u06cc \u0642\u0644\u0628\u06cc\u200c\u0639\u0631\u0648\u0642\u06cc \u0622\u0633\u06cc\u0628\u200c\u067e\u0630\u06cc\u0631 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0642\u0631\u0627\u0631 \u06af\u0631\u0641\u062a\u0646 \u0645\u0632\u0645\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0632\u06cc\u0631 \u0627\u062b\u0631 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0628\u062f\u0648\u0646 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646\u060c \u062e\u0637\u0631 \u0647\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc/\u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u06cc\u200c\u06cc\u0627\u0628\u062f\u061b \u0622\u0633\u06cc\u0628 \u06a9\u0644\u06cc\u0648\u06cc \u0645\u0632\u0645\u0646 \u062c\u0632\u0648 \u067e\u06cc\u0627\u0645\u062f\u0647\u0627\u06cc \u0645\u0633\u062a\u0642\u06cc\u0645 \u0648 \u0634\u0627\u06cc\u0639 PCOS \u0646\u06cc\u0633\u062a \u0648 \u0646\u0628\u0627\u06cc\u062f \u062f\u0631 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a \u0642\u0631\u0627\u0631 \u062f\u0627\u0634\u062a\u0647 \u0628\u0627\u0634\u062f.",
   "reasons": ["\u0628\u06cc\u0645\u0627\u0631\u06cc \u0642\u0644\u0628\u06cc\u200c\u0639\u0631\u0648\u0642\u06cc \u0627\u0632 \u0639\u0648\u0627\u0631\u0636 \u062f\u06cc\u0631\u0631\u0633 \u0645\u0631\u062a\u0628\u0637 \u0628\u0627 PCOS \u0627\u0633\u062a.", "\u062f\u06cc\u0627\u0628\u062a \u0646\u0648\u0639 \u06f2 \u0627\u0632 \u0639\u0648\u0627\u0631\u0636 \u0645\u062a\u0627\u0628\u0648\u0644\u06cc\u06a9 \u0631\u0627\u06cc\u062c PCOS \u0627\u0633\u062a.", "\u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u06a9\u0644\u06cc\u0648\u06cc \u062c\u0632\u0621 \u0639\u0648\u0627\u0631\u0636 \u0645\u0633\u062a\u0642\u06cc\u0645 \u0634\u0627\u06cc\u0639 PCOS \u0646\u06cc\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u062a\u062d\u0631\u06cc\u06a9 \u0627\u0633\u062a\u0631\u0648\u0698\u0646\u06cc \u0628\u062f\u0648\u0646 \u0645\u0642\u0627\u0628\u0644 \u062f\u0631 PCOS \u0628\u06cc\u0634\u200c\u062a\u0631 \u0645\u06cc\u200c\u0634\u0648\u062f."],
  },
  (28, 52): {
   "topic": "papEndometrialCellsPmp",
   "lead": "\u0645\u0634\u0627\u0647\u062f\u0647\u0654 \u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc \u062f\u0631 \u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 \u0632\u0646 \u06cc\u0627\u0626\u0633\u0647\u200c\u0627\u06cc \u06a9\u0647 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0647\u0645 \u0646\u062f\u0627\u0631\u062f: \u0628\u0627\u06cc\u062f \u0628\u0631\u0627\u06cc \u0628\u062f\u062e\u06cc\u0645\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0631\u0631\u0633\u06cc \u0634\u0648\u062f \u062a\u0627 \u0642\u0637\u0639\u06cc \u0631\u062f \u0634\u0648\u062f.",
   "interpretation": "\u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc \u062e\u0648\u0634\u200c\u0638\u0627\u0647\u0631 \u062f\u0631 \u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 \u0632\u0646\u0627\u0646 \u0628\u0627\u0644\u0627\u06cc \u06f4\u06f5 \u0633\u0627\u0644/\u06cc\u0627\u0626\u0633\u0647 \u0628\u0647\u200c\u062e\u0648\u062f\u06cc\u200c\u062e\u0648\u062f \u00ab\u0646\u0631\u0645\u0627\u0644\u00bb \u062a\u0644\u0642\u06cc \u0646\u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0646\u0634\u0627\u0646\u200c\u062f\u0647\u0646\u062f\u0647\u0654 \u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc/\u0628\u062f\u062e\u06cc\u0645\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u06cc\u0627 \u062d\u062a\u06cc \u0646\u0634\u062a \u0636\u0627\u06cc\u0639\u0647\u0654 \u0644\u0648\u0644\u0647/\u062a\u062e\u0645\u062f\u0627\u0646 \u0628\u0627\u0634\u062f\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u0628\u0631\u0631\u0633\u06cc \u0628\u06cc\u0645\u0627\u0631 \u0627\u0632 \u0645\u0646\u0638\u0631 \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 (\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0627\u0646\u062f\u0627\u0632\u0647\u0654 \u06af\u06cc\u0631\u06cc \u0644\u0627\u06cc\u0647 \u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u0644\u0632\u0648\u0645 \u0628\u06cc\u0648\u067e\u0633\u06cc) \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u0646\u0647 \u0635\u0631\u0641 \u062a\u06a9\u0631\u0627\u0631 \u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 \u06cc\u0627 \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u06cc\u0627 \u062a\u0633\u062a HPV \u06a9\u0647 \u0627\u0628\u0632\u0627\u0631\u0647\u0627\u06cc \u0633\u0631\u0637\u0627\u0646 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0647\u0633\u062a\u0646\u062f.",
   "reasons": ["\u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0627\u0633\u062a \u0646\u0647 \u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc \u0645\u0634\u0627\u0647\u062f\u0647\u200c\u0634\u062f\u0647.", "\u062a\u06a9\u0631\u0627\u0631 \u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 \u0628\u062f\u0648\u0646 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062f\u0631 \u06cc\u0627\u0626\u0633\u0647 \u062a\u0635\u0645\u06cc\u0645\u200c\u0633\u0627\u0632 \u0646\u06cc\u0633\u062a.", "\u0628\u0631\u0631\u0633\u06cc \u0628\u0631\u0627\u06cc \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 (\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc/\u0628\u06cc\u0648\u067e\u0633\u06cc \u062f\u0631 \u0635\u0648\u0631\u062a \u0644\u0632\u0648\u0645) \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u0633\u062a HPV \u0628\u0631\u0627\u06cc \u0628\u0631\u0631\u0633\u06cc \u062f\u0647\u0627\u0646\u0647\u0654 \u0631\u062d\u0645 \u0627\u0633\u062a \u0648 \u0648\u0636\u0639\u06cc\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc \u0631\u0627 \u0631\u0648\u0634\u0646 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f."],
  },
  (28, 53): {
   "topic": "gdmPostpartumTest",
   "lead": "\u067e\u0633 \u0627\u0632 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 GDM (\u0645\u062b\u0628\u062a \u062f\u0631 \u062f\u0648 \u0645\u0631\u062d\u0644\u0647), \u062f\u0631 \u0648\u06cc\u0632\u06cc\u062a \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062a\u0633\u062a OGTT \u062f\u0648\u200c\u0633\u0627\u0639\u062a\u0647 \u0628\u0627 \u06f7\u06f5 \u06af\u0631\u0645 \u06af\u0644\u0648\u06a9\u0632 \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u062a\u0627 \u062f\u06cc\u0627\u0628\u062a \u067e\u0627\u06cc\u062f\u0627\u0631 \u0631\u062f \u0634\u0648\u062f.",
   "interpretation": "\u0632\u0646\u0627\u0646\u06cc \u06a9\u0647 \u062f\u06cc\u0627\u0628\u062a \u062d\u0627\u0645\u0644\u06af\u06cc \u062f\u0627\u0634\u062a\u0647\u200c\u0627\u0646\u062f \u062f\u0631 \u06f4-\u06f1\u06f2 \u0647\u0641\u062a\u0647\u0654 \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0628\u0627\u06cc\u062f \u0628\u0627 \u0622\u0632\u0645\u0648\u0646 \u062a\u062d\u0645\u0644 \u06af\u0644\u0648\u06a9\u0632 \u062e\u0648\u0631\u0627\u06a9\u06cc \u062f\u0648 \u0633\u0627\u0639\u062a\u0647 \u0628\u0627 \u062f\u0648\u0632 \u06f7\u06f5 \u06af\u0631\u0645 (\u0647\u0645\u0627\u0646 \u0622\u0632\u0645\u0648\u0646 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u062f\u06cc\u0627\u0628\u062a \u0628\u0632\u0631\u06af\u0633\u0627\u0644) \u0631\u062f \u0634\u0648\u0646\u062f \u062a\u0627 \u0631\u06cc\u0633\u06a9 \u062a\u0628\u062f\u06cc\u0644 \u0628\u0647 \u062f\u06cc\u0627\u0628\u062a \u0646\u0648\u0639 \u062f\u0648 \u0645\u0634\u062e\u0635 \u0634\u0648\u062f\u061b \u062a\u06a9\u0631\u0627\u0631 \u062a\u0633\u062a \u06f5\u06f0 \u06af\u0631\u0645\u06cc \u06cc\u0627 OGTT \u0633\u0647\u200c\u0633\u0627\u0639\u062a\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u062f\u0648\u0631\u0627\u0646 \u0646\u0641\u0627\u0633 \u062c\u0627\u06cc\u06af\u0627\u0647 \u0648\u06cc\u0698\u0647 \u0646\u062f\u0627\u0631\u062f \u0648 HbA1c \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u0646\u0631\u0645\u0627\u0644\u200c\u0646\u0645\u0627\u06cc \u0628\u0627\u0634\u062f \u0648 OGTT \u062f\u0648 \u0633\u0627\u0639\u062a\u0647 \u0628\u0647 \u062f\u0644\u06cc\u0644 \u062a\u0634\u062e\u06cc\u0635 \u06a9\u0627\u0647\u0634 \u062a\u062d\u0645\u0644 \u06af\u0644\u0648\u06a9\u0632 \u0645\u0642\u062f\u0645\u200c\u062a\u0631 \u0627\u0633\u062a.",
   "reasons": ["OGTT \u0633\u0647\u200c\u0633\u0627\u0639\u062a\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u0646\u0641\u0627\u0633 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.", "\u062a\u0633\u062a \u06f5\u06f0 \u06af\u0631\u0645\u06cc \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u062f\u06cc\u0627\u0628\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a \u0648 \u062f\u0631 \u062f\u0648\u0631\u0627\u0646 \u0646\u0641\u0627\u0633 \u06a9\u0627\u0631\u0628\u0631\u062f \u0645\u062a\u0639\u0627\u0631\u0641 \u0646\u062f\u0627\u0631\u062f.", "OGTT \u062f\u0648 \u0633\u0627\u0639\u062a\u0647\u0654 \u06f7\u06f5 \u06af\u0631\u0645\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "HbA1c \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062f\u0631 \u0631\u062f \u06a9\u0627\u0647\u0634 \u062a\u062d\u0645\u0644 \u06af\u0644\u0648\u06a9\u0632 \u067e\u0633\u0627\u0632-\u0632\u0627\u06cc\u0645\u0627\u0646 \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a \u0648 \u062c\u0627\u06cc OGTT \u0631\u0627 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u062f."],
  },
  (28, 54): {
   "topic": "papStartIran",
   "lead": "\u0628\u0631\u0627\u06cc \u0632\u0646\u06cc \u06a9\u0647 \u06f3 \u0633\u0627\u0644 \u067e\u06cc\u0634 \u0648\u0627\u0631\u062f \u0632\u0646\u062f\u06af\u06cc \u0632\u0646\u0627\u0634\u0648\u06cc\u06cc \u0634\u062f\u0647\u060c \u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 \u0627\u0632 \u0647\u0645\u200c\u0627\u06a9\u0646\u0648\u0646 \u0637\u0628\u0642 \u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc (\u0633\u0647 \u0633\u0627\u0644 \u067e\u0633 \u0627\u0632 \u0622\u063a\u0627\u0632 \u0645\u0642\u0627\u0631\u0628\u062a) \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "interpretation": "\u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0633\u0631\u0637\u0627\u0646 \u062f\u0647\u0627\u0646\u0647\u0654 \u0631\u062d\u0645 \u0634\u0631\u0648\u0639 \u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 \u0631\u0627 \u0633\u0647 \u0633\u0627\u0644 \u067e\u0633 \u0627\u0632 \u0622\u063a\u0627\u0632 \u0641\u0639\u0627\u0644\u06cc\u062a \u062c\u0646\u0633\u06cc \u0645\u0646\u0638\u0645 (\u06cc\u0627 \u0627\u0632\u062f\u0648\u0627\u062c) \u0645\u06cc\u200c\u062f\u0627\u0646\u062f\u061b \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631 \u06f1\u06f7 \u0633\u0627\u0644\u0647 \u0628\u0627 \u0633\u0647 \u0633\u0627\u0644 \u0627\u0632\u062f\u0648\u0627\u062c \u0627\u0632 \u0647\u0645\u200c\u0627\u06a9\u0646\u0648\u0646 \u06a9\u0627\u0646\u062f\u06cc\u062f \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0627\u0633\u062a\u061b \u0622\u0633\u062a\u0627\u0646\u0647\u0654 \u06f1\u06f8 \u0633\u0627\u0644\u06af\u06cc \u0648 \u00ab\u067e\u0633 \u0627\u0632 \u0627\u0648\u0644\u06cc\u0646 \u0632\u0627\u06cc\u0645\u0627\u0646\u00bb \u0645\u0628\u0627\u0646\u06cc \u0642\u062f\u06cc\u0645\u06cc \u06cc\u0627 \u0646\u0627\u0645\u0631\u0628\u0648\u0637\u200c\u0627\u0646\u062f \u0648 \u06f3\u06f0 \u0633\u0627\u0644\u06af\u06cc \u0645\u0628\u0646\u0627\u06cc \u062a\u063a\u06cc\u06cc\u0631 \u0646\u0648\u0639 \u062a\u0633\u062a (\u0627\u0641\u0632\u0648\u062f\u0646 HPV co-test) \u0627\u0633\u062a \u0646\u0647 \u0646\u0642\u0637\u0647\u0654 \u0634\u0631\u0648\u0639 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u062f\u0631 \u0686\u0646\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631\u06cc.",
   "reasons": ["\u06f1\u06f8 \u0633\u0627\u0644\u06af\u06cc \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0641\u0639\u0644\u06cc \u0634\u0631\u0648\u0639 \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0646\u06cc\u0633\u062a.", "\u06f3\u06f0 \u0633\u0627\u0644\u06af\u06cc \u0646\u0642\u0637\u0647\u0654 \u062a\u063a\u06cc\u06cc\u0631 \u0631\u0648\u0634 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0627\u0633\u062a \u0646\u0647 \u0634\u0631\u0648\u0639 \u0622\u0646.", "\u0633\u0647 \u0633\u0627\u0644 \u0627\u0632\u062f\u0648\u0627\u062c \u06cc\u0639\u0646\u06cc \u0647\u0645\u200c\u0627\u06a9\u0646\u0648\u0646 \u0634\u0631\u0648\u0639 \u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u067e\u0633 \u0627\u0632 \u0627\u0648\u0644\u06cc\u0646 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0645\u0644\u0627\u06a9 \u0634\u0631\u0648\u0639 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0646\u06cc\u0633\u062a."],
  },
  (28, 56): {
   "topic": "inevitableAbortion",
   "lead": "\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0648 \u062f\u0631\u062f \u06a9\u0648\u0644\u06cc\u06a9\u06cc \u06f1\u06f2 \u0647\u0641\u062a\u0647 \u0628\u0627 \u062e\u0631\u0648\u062c \u062a\u0631\u0634\u062d \u0622\u0628\u06a9\u06cc \u0627\u0632 \u062f\u0647\u0627\u0646\u0647\u0654 \u0633\u0631\u0648\u06cc\u06a9\u0633: \u067e\u0631\u062f\u0647 \u067e\u0627\u0631\u0647 \u0627\u0633\u062a \u0648 \u0633\u0642\u0637 \u0627\u062c\u062a\u0646\u0627\u0628\u200c\u0646\u0627\u067e\u0630\u06cc\u0631 \u062c\u0631\u06cc\u0627\u0646 \u062f\u0627\u0631\u062f.",
   "interpretation": "\u0647\u0631\u06af\u0627\u0647 \u0639\u0644\u0627\u06cc\u0645 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0648 \u062f\u0631\u062f \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 \u0628\u0627 \u0645\u0634\u0627\u0647\u062f\u0647\u0654 \u062f\u0647\u0627\u0646\u0647\u0654 \u0628\u0627\u0632 \u06cc\u0627 \u062e\u0631\u0648\u062c \u0645\u062d\u062a\u0648\u06cc\u0627\u062a/\u062a\u0631\u0634\u062d \u0622\u0628\u06a9\u06cc (\u067e\u0627\u0631\u06af\u06cc \u067e\u0631\u062f\u0647) \u0627\u0632 \u062f\u0647\u0627\u0646\u0647\u0654 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0647\u0645\u0631\u0627\u0647 \u0634\u0648\u062f\u060c \u0627\u0645\u06a9\u0627\u0646 \u067e\u06cc\u0634\u200c\u06af\u06cc\u0631\u06cc \u0627\u0632 \u0633\u0642\u0637 \u0648\u062c\u0648\u062f \u0646\u062f\u0627\u0631\u062f \u0648 \u0641\u0631\u0627\u06cc\u0646\u062f \u00ab\u0627\u062c\u062a\u0646\u0627\u0628\u200c\u0646\u0627\u067e\u0630\u06cc\u0631\u00bb \u0646\u0627\u0645\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u062a\u0647\u062f\u06cc\u062f \u0628\u0647 \u0633\u0642\u0637 \u0628\u0627 \u062f\u0647\u0627\u0646\u0647\u0654 \u0628\u0633\u062a\u0647 \u0648 \u067e\u0631\u062f\u0647\u0654 \u0633\u0627\u0644\u0645 \u0645\u06cc\u200c\u0622\u06cc\u062f\u060c \u0633\u0642\u0637 \u0641\u0631\u0627\u0645\u0648\u0634\u200c\u0634\u062f\u0647 \u062c\u0646\u06cc\u0646 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u06cc\u0645 \u062e\u0631\u0648\u062c \u0627\u0633\u062a \u0648 \u0633\u0642\u0637 \u06a9\u0627\u0645\u0644 \u06cc\u0639\u0646\u06cc \u062a\u062e\u0644\u06cc\u0647\u0654 \u06a9\u0627\u0645\u0644 \u0645\u062d\u062a\u0648\u06cc\u0627\u062a \u06a9\u0647 \u0647\u0646\u0648\u0632 \u0631\u062e \u0646\u062f\u0627\u062f\u0647 \u0627\u0633\u062a.",
   "reasons": ["\u062a\u0647\u062f\u06cc\u062f \u0628\u0647 \u0633\u0642\u0637 \u0628\u0627 \u062f\u0647\u0627\u0646\u0647\u0654 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0633\u062a\u0647 \u0648 \u067e\u0631\u062f\u0647\u0654 \u0633\u0627\u0644\u0645 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0633\u0642\u0637 \u0641\u0631\u0627\u0645\u0648\u0634\u200c\u0634\u062f\u0647 \u062f\u0631 \u063a\u06cc\u0627\u0628 \u0639\u0644\u0627\u06cc\u0645 \u062e\u0631\u0648\u062c \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0633\u0642\u0637 \u06a9\u0627\u0645\u0644 \u06cc\u0639\u0646\u06cc \u0647\u0645\u0647\u0654 \u0645\u062d\u062a\u0648\u06cc\u0627\u062a \u062e\u0627\u0631\u062c \u0634\u062f\u0647\u200c\u0627\u0646\u062f \u06a9\u0647 \u062f\u0631 \u0627\u06cc\u0646\u062c\u0627 \u0641\u0642\u0637 \u0634\u0631\u0648\u0639 \u062e\u0631\u0648\u062c \u0627\u0633\u062a.", "\u062f\u0647\u0627\u0646\u0647\u0654 \u0628\u0627\u0632 \u0628\u0627 \u062e\u0631\u0648\u062c \u062a\u0631\u0634\u062d \u0622\u0628\u06a9\u06cc \u062a\u0639\u0631\u06cc\u0641 \u0633\u0642\u0637 \u0627\u062c\u062a\u0646\u0627\u0628\u200c\u0646\u0627\u067e\u0630\u06cc\u0631 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 58): {
   "topic": "severePreeclampsiaFeatures",
   "lead": "\u0641\u0634\u0627\u0631 \u06f1\u06f4\u06f0/80 + \u067e\u0644\u0627\u06a9\u062a \u06f9\u06f0\u066c\u06f0\u06f0\u06f0 + AST=\u06f7\u06f6 \u062f\u0631 \u06f3\u06f4 \u0647\u0641\u062a\u0647: \u0627\u06cc\u0646 \u062a\u0631\u06a9\u06cc\u0628 \u0645\u0644\u0627\u06a9\u200c\u0647\u0627\u06cc \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0628\u0627 \u0639\u0644\u0627\u06cc\u0645 \u0634\u062f\u06cc\u062f \u0631\u0627 \u062f\u0627\u0631\u062f \u0648 \u0627\u0642\u062f\u0627\u0645 \u062f\u0631\u0633\u062a \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u0648 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u0647\u0631 \u06cc\u06a9 \u0627\u0632 \u0645\u0648\u0627\u0631\u062f \u00ab\u062a\u0631\u0648\u0645\u0628\u0648\u0633\u06cc\u062a\u0648\u067e\u0646\u06cc \u06a9\u0645\u062a\u0631 \u0627\u0632 \u06f1\u06f0\u06f0 \u0647\u0632\u0627\u0631\u00bb\u060c \u00ab\u0627\u0641\u0632\u0627\u06cc\u0634 AST/ALT \u0628\u06cc\u0634 \u0627\u0632 \u062f\u0648 \u0628\u0631\u0627\u0628\u0631 \u062d\u062f \u0637\u0628\u06cc\u0639\u06cc\u00bb \u0648 \u00ab\u0641\u0634\u0627\u0631 \u0628\u0627\u0644\u0627\u06cc \u06f1\u06f6\u06f0/\u06f1\u06f1\u06f0\u00bb \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0628\u06cc\u0645\u0627\u0631\u06cc \u0631\u0627 \u0628\u0647\u200c\u0635\u0648\u0631\u062a \u00ab\u0639\u0644\u0627\u06cc\u0645 \u0634\u062f\u06cc\u062f\u00bb \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u062f\u0631 \u06f3\u06f4 \u0647\u0641\u062a\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062e\u062a\u0645 \u0628\u0627 \u067e\u0648\u0634\u0634 \u067e\u06cc\u0634\u06af\u06cc\u0631\u06cc \u0627\u0632 \u062a\u0634\u0646\u062c (\u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645) \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0627\u0633\u062a\u061b \u06a9\u0648\u0631\u062a\u0648\u0646 \u0631\u0627 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646 \u0647\u0645\u0631\u0627\u0647 \u062f\u0627\u062f \u0648\u0644\u06cc \u062a\u0641\u0633\u06cc\u0631 \u00ab\u0627\u0646\u062a\u0638\u0627\u0631 \u062a\u0627 \u06f3\u06f7 \u0647\u0641\u062a\u0647\u00bb \u062f\u0631 \u0639\u0644\u0627\u06cc\u0645 \u0634\u062f\u06cc\u062f \u067e\u0630\u06cc\u0631\u0641\u062a\u0646\u06cc \u0646\u06cc\u0633\u062a \u0648 \u062f\u0627\u067e\u0644\u0631 \u0634\u0631\u06cc\u0627\u0646 \u0646\u0627\u0641\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0634\u0631\u0627\u06cc\u0637 \u062a\u0635\u0645\u06cc\u0645\u200c\u0633\u0627\u0632 \u0627\u0635\u0644\u06cc \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u062f\u0631 \u0639\u0644\u0627\u06cc\u0645 \u0634\u062f\u06cc\u062f \u062a\u0627\u062e\u06cc\u0631 \u062f\u0631 \u062e\u062a\u0645 \u062e\u0637\u0631\u0646\u0627\u06a9 \u0627\u0633\u062a \u0648 \u06a9\u0648\u0631\u062a\u0648\u0646 \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.", "\u062f\u0627\u067e\u0644\u0631 \u0634\u0631\u06cc\u0627\u0646 \u0646\u0627\u0641\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0645\u06a9\u0645\u0644 \u0627\u0633\u062a \u0646\u0647 \u062a\u0635\u0645\u06cc\u0645 \u062e\u062a\u0645.", "\u0639\u0644\u0627\u06cc\u0645 \u0634\u062f\u06cc\u062f \u062f\u0627\u0631\u062f \u0648 \u0633\u0648\u0644\u0641\u0627\u062a + \u062e\u062a\u0645 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0646\u06af\u0647\u200c\u062f\u0627\u0634\u062a\u0646 \u062a\u0627 \u06f3\u06f7 \u0647\u0641\u062a\u0647 \u062f\u0631 \u0639\u0644\u0627\u06cc\u0645 \u0634\u062f\u06cc\u062f \u0627\u0634\u062a\u0628\u0627\u0647 \u0627\u0633\u062a."],
  },
  (28, 59): {
   "topic": "eclampsiaMgFirst",
   "lead": "\u062a\u0634\u0646\u062c \u062a\u0648\u0646\u06cc\u06a9-\u06a9\u0644\u0648\u0646\u06cc\u06a9 + \u0641\u0634\u0627\u0631 \u06f1\u06f8\u06f0/\u06f1\u06f2\u06f0 \u062f\u0631 \u06f3\u06f3 \u0647\u0641\u062a\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc: \u062a\u0634\u062e\u06cc\u0635 \u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0648 \u062f\u0627\u0631\u0648\u06cc \u062e\u0637 \u0627\u0648\u0644\u060c \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 (\u0628\u0631\u0627\u06cc \u0645\u0647\u0627\u0631 \u0648 \u067e\u06cc\u0634\u06af\u06cc\u0631\u06cc \u0627\u0632 \u0639\u0648\u062f \u062a\u0634\u0646\u062c).",
   "interpretation": "\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062a\u0627 \u0632\u0645\u0627\u0646 \u0627\u062b\u0628\u0627\u062a \u0639\u06a9\u0633 \u0647\u0631 \u062a\u0634\u0646\u062c \u062f\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0633\u0648\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u062f\u06cc\u0631\u06cc\u062a \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u062f\u0627\u0631\u0648\u06cc \u0627\u0646\u062a\u062e\u0627\u0628\u06cc \u0627\u0648\u0644\u06cc\u0647\u060c \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u0627\u0633\u062a \u0686\u0648\u0646 \u0628\u0647\u062a\u0631 \u0627\u0632 \u0641\u0646\u06cc\u200c\u062a\u0648\u0626\u06cc\u0646 \u0648 \u062f\u06cc\u0627\u0632\u067e\u0627\u0645 \u062a\u0634\u0646\u062c \u0631\u0627 \u06a9\u0646\u062a\u0631\u0644 \u0648 \u0627\u0632 \u0639\u0648\u062f \u067e\u06cc\u0634\u06af\u06cc\u0631\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f\u061b \u0627\u0646\u062a\u0648\u0628\u0627\u0633\u06cc\u0648\u0646 \u0641\u0642\u0637 \u062f\u0631 \u0622\u067e\u0646\u0647/\u0646\u0627\u06a9\u0627\u0645\u06cc \u062a\u0646\u0641\u0633\u06cc \u0627\u0633\u062a \u0648 \u0647\u0645\u0647\u0654 \u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc\u200c\u0647\u0627 \u062e\u0648\u062f\u0628\u0647\u200c\u062e\u0648\u062f \u0646\u06cc\u0627\u0632 \u0646\u062f\u0627\u0631\u0646\u062f\u060c \u062e\u0648\u0627\u0628\u06cc\u062f\u0646 \u0628\u0647\u200c\u067e\u0634\u062a \u0641\u0634\u0627\u0631 \u0631\u062d\u0645 \u0628\u0647 \u0648\u0631\u06cc\u062f \u0627\u062c\u0648\u0641 \u0631\u0627 \u0628\u062f\u062a\u0631 \u0645\u06cc\u200c\u06a9\u0646\u062f (\u0648\u0636\u0639\u06cc\u062a \u0686\u067e\u200c\u067e\u0647\u0644\u0648 \u0628\u0647\u062a\u0631 \u0627\u0633\u062a) \u0648 \u06a9\u0648\u0631\u062a\u0648\u0646+\u062e\u062a\u0645 \u067e\u0633 \u0627\u0632 \u067e\u0627\u06cc\u062f\u0627\u0631\u0634\u062f\u0646 \u0645\u0627\u062f\u0631 \u0627\u0633\u062a\u060c \u0646\u0647 \u0628\u0647\u200c\u062c\u0627\u06cc \u0645\u0647\u0627\u0631 \u062a\u0634\u0646\u062c.",
   "reasons": ["\u0627\u0646\u062a\u0648\u0628\u0627\u0633\u06cc\u0648\u0646 \u0631\u0648\u062a\u06cc\u0646 \u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0646\u06cc\u0633\u062a \u0648 \u0641\u0642\u0637 \u062f\u0631 \u0646\u0627\u06a9\u0627\u0645\u06cc \u062a\u0646\u0641\u0633\u06cc \u0645\u0624\u06cc\u062f \u0627\u0633\u062a.", "\u0648\u0636\u0639\u06cc\u062a \u062f\u0631\u0627\u0632\u06a9\u0634 \u0628\u0647\u200c\u067e\u0634\u062a \u0641\u0634\u0627\u0631 \u0628\u0647 \u0648\u0631\u06cc\u062f \u0627\u062c\u0648\u0641 \u0631\u0627 \u0632\u06cc\u0627\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f\u061b \u0686\u067e\u200c\u067e\u0647\u0644\u0648 \u062a\u0631\u062c\u06cc\u062d \u062f\u0627\u0631\u062f.", "\u0634\u0631\u0648\u0639 \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u0627\u0642\u062f\u0627\u0645 \u062e\u0637 \u0627\u0648\u0644 \u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06a9\u0648\u0631\u062a\u0648\u0646 \u0648 \u062e\u062a\u0645 \u067e\u0633 \u0627\u0632 \u067e\u0627\u06cc\u062f\u0627\u0631\u0634\u062f\u0646 \u0645\u0627\u062f\u0631 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f \u0646\u0647 \u0628\u0647\u200c\u062c\u0627\u06cc \u0645\u0647\u0627\u0631 \u062a\u0634\u0646\u062c."],
  },
  (28, 60): {
   "topic": "labetalolAsthmaPreeclampsia",
   "lead": "\u062f\u0631 \u0628\u06cc\u0645\u0627\u0631 \u0622\u0633\u0645\u06cc \u0628\u0627 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0634\u062f\u06cc\u062f\u060c \u0644\u0627\u0628\u0650\u062a\u0627\u0644\u0648\u0644 (\u0628\u0644\u0648\u06a9\u200c\u06a9\u0646\u0646\u062f\u0647\u0654 \u0628\u062a\u0627) \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u062e\u0637\u0631 \u0628\u0631\u0648\u0646\u06a9\u0648\u0627\u0633\u067e\u0627\u0633\u0645 \u0627\u0646\u062a\u062e\u0627\u0628 \u0646\u0627\u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a\u061b \u0647\u06cc\u062f\u0631\u0627\u0644\u0627\u0632\u06cc\u0646\u060c \u0646\u06cc\u0641\u06cc\u062f\u06cc\u067e\u06cc\u0646 \u0648 NTG \u0645\u062c\u0627\u0632\u0646\u062f.",
   "interpretation": "\u062f\u0631 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u0641\u0634\u0627\u0631\u062e\u0648\u0646 \u062f\u0648\u0631\u0627\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u060c \u0647\u06cc\u062f\u0631\u0627\u0644\u0627\u0632\u06cc\u0646/\u0644\u0627\u0628\u0650\u062a\u0627\u0644\u0648\u0644/\u0646\u06cc\u0641\u06cc\u062f\u06cc\u067e\u06cc\u0646 \u0627\u0632 \u062f\u0627\u0631\u0648\u0647\u0627\u06cc \u0631\u0627\u06cc\u062c\u200c\u0627\u0646\u062f \u0648 \u062a\u0631\u06cc\u200c\u0646\u06cc\u062a\u0631\u0648\u06af\u0644\u06cc\u0633\u06cc\u0631\u06cc\u0646 \u0646\u06cc\u0632 \u062f\u0631 \u0645\u0648\u0627\u0631\u062f \u062e\u0627\u0635 \u0645\u0635\u0631\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f \u0627\u0645\u0627 \u0628\u06cc\u0645\u0627\u0631\u06cc \u06a9\u0647 \u0622\u0633\u0645 \u0641\u0639\u0627\u0644 \u06cc\u0627 \u0627\u062e\u06cc\u0631 \u062f\u0627\u0631\u062f \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u0627\u062b\u0631 \u0628\u062a\u0627\u0628\u0644\u0627\u06a9\u200c\u06a9\u0646\u0646\u062f\u0647\u0654 \u0644\u0627\u0628\u0650\u062a\u0627\u0644\u0648\u0644 \u062f\u0631 \u0645\u0639\u0631\u0636 \u0628\u0631\u0648\u0646\u06a9\u0648\u0627\u0633\u067e\u0627\u0633\u0645 \u0642\u0631\u0627\u0631 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f \u0648 \u0627\u06cc\u0646 \u062f\u0627\u0631\u0648 \u062f\u0631 \u0622\u0646\u200c\u0647\u0627 \u0646\u0633\u0628\u062a\u0627\u064b \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u062f\u0631 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a \u00ab\u062c\u0632\u0621\u00bb\u060c \u0644\u0627\u0628\u0650\u062a\u0627\u0644\u0648\u0644 \u0627\u0633\u062a.",
   "reasons": ["\u0647\u06cc\u062f\u0631\u0627\u0644\u0627\u0632\u06cc\u0646 \u062f\u0631 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u0641\u0634\u0627\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u062c\u0627\u0632 \u0627\u0633\u062a.", "\u0644\u0627\u0628\u0650\u062a\u0627\u0644\u0648\u0644 \u0628\u0627 \u0622\u0633\u0645 \u0641\u0639\u0627\u0644 \u0645\u0646\u0639 \u0646\u0633\u0628\u06cc \u062f\u0627\u0631\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d (\u0627\u0633\u062a\u062b\u0646\u0627).", "\u0646\u06cc\u0641\u06cc\u062f\u06cc\u067e\u06cc\u0646 \u062e\u0648\u0631\u0627\u06a9\u06cc \u062f\u0631 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u0641\u0634\u0627\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u06a9\u0627\u0631 \u0645\u06cc\u200c\u0631\u0648\u062f.", "\u0646\u06cc\u062a\u0631\u0648\u06af\u0644\u06cc\u0633\u06cc\u0631\u06cc\u0646 \u062f\u0631 \u0645\u0648\u0627\u0631\u062f \u062e\u0627\u0635 \u0642\u0627\u0628\u0644\u200c\u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0633\u062a."],
  },
  (28, 61): {
   "topic": "periodontalPreterm",
   "lead": "\u0628\u06cc\u0645\u0627\u0631\u06cc \u067e\u0631\u06cc\u0648\u062f\u0646\u062a\u0627\u0644 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u062e\u0637\u0631 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 (\u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0644\u06cc\u0628\u0631) \u0628\u06cc\u0634\u200c\u062a\u0631\u06cc\u0646 \u0627\u0631\u062a\u0628\u0627\u0637 \u0631\u0627 \u062f\u0627\u0631\u062f.",
   "interpretation": "\u0627\u0644\u062a\u0647\u0627\u0628 \u0645\u0632\u0645\u0646 \u0644\u062b\u0647/\u062f\u0646\u062f\u0627\u0646 \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u0628\u0627\u0631 \u0645\u06cc\u06a9\u0631\u0648\u0628\u06cc \u0648 \u0627\u0644\u062a\u0647\u0627\u0628 \u0633\u06cc\u0633\u062a\u0645\u06cc\u06a9\u060c \u0628\u0627 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0633\u06cc\u062a\u0648\u06a9\u06cc\u0646\u200c\u0647\u0627 \u0648 \u067e\u0631\u0648\u0633\u062a\u0627\u06af\u0644\u0627\u0646\u062f\u06cc\u0646\u200c\u0647\u0627 \u067e\u06cc\u0648\u0646\u062f \u062e\u0648\u0631\u062f\u0647 \u0648 \u062f\u0631 \u0645\u0637\u0627\u0644\u0639\u0627\u062a \u0627\u067e\u06cc\u062f\u0645\u06cc\u0648\u0644\u0648\u0698\u06cc\u06a9 \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0639\u0627\u0631\u0636\u0647\u0654 \u0645\u0631\u062a\u0628\u0637 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0622\u0646\u060c \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0627\u0633\u062a\u061b \u0627\u062b\u0631 \u0628\u0631 \u0631\u0634\u062f \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u06cc\u0627 \u067e\u0627\u0631\u06af\u06cc \u0632\u0648\u062f\u0631\u0633 \u067e\u0631\u062f\u0647\u200c\u0647\u0627 \u0628\u0647\u200c\u0645\u0631\u0627\u062a\u0628 \u06a9\u0645\u200c\u062a\u0648\u0627\u062a\u0631 \u0648 \u06a9\u0645\u200c\u0627\u0633\u062a\u062f\u0644\u0627\u0644\u200c\u062a\u0631 \u0627\u0633\u062a \u0648 \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633+\u0645\u0631\u06af \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u067e\u06cc\u0627\u0645\u062f \u0634\u062f\u06cc\u062f \u0648 \u0646\u0627\u062f\u0631 \u0627\u0633\u062a.",
   "reasons": ["\u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0645\u062d\u062a\u0645\u0644\u200c\u062a\u0631\u06cc\u0646 \u0639\u0627\u0631\u0636\u0647\u0654 \u0645\u0631\u062a\u0628\u0637 \u0628\u0627 \u0628\u06cc\u0645\u0627\u0631\u06cc \u067e\u0631\u06cc\u0648\u062f\u0646\u062a\u0627\u0644 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0645\u062d\u062f\u0648\u062f\u06cc\u062a \u0631\u0634\u062f \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u0627\u0631\u062a\u0628\u0627\u0637 \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc \u0628\u0627 \u0639\u0648\u0627\u0645\u0644 \u062c\u0641\u062a/\u0641\u0634\u0627\u0631 \u062f\u0627\u0631\u062f.", "\u067e\u0627\u0631\u06af\u06cc \u0632\u0648\u062f\u0631\u0633 \u067e\u0631\u062f\u0647 \u0627\u0631\u062a\u0628\u0627\u0637 \u06a9\u0645\u062a\u0631\u06cc \u0628\u0627 \u067e\u0631\u06cc\u0648\u062f\u0646\u062a\u0627\u0644 \u062f\u0627\u0631\u062f.", "\u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0648 \u0645\u0631\u06af \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u067e\u06cc\u0627\u0645\u062f \u0634\u062f\u06cc\u062f \u0648 \u0646\u0627\u062f\u0631 \u0627\u06cc\u0646 \u062a\u0639\u0627\u0645\u0644 \u0627\u0633\u062a."],
  },
  (28, 62): {
   "topic": "myomaAsymptomaticObserve",
   "lead": "\u0645\u06cc\u0648\u0645\u200c\u0647\u0627\u06cc \u06a9\u0648\u0686\u06a9 (\u06f2-\u06f4 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631) \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u062f\u0631 \u0632\u0646 \u06f4\u06f0 \u0633\u0627\u0644\u0647\u0654 \u0645\u0648\u0644\u062a\u06cc\u200c\u067e\u0627\u0631: \u0646\u06cc\u0627\u0632 \u0628\u0647 \u0627\u0642\u062f\u0627\u0645 \u062f\u0631\u0645\u0627\u0646\u06cc \u0646\u06cc\u0633\u062a \u0648 \u067e\u0627\u06cc\u0634/\u0627\u0637\u0645\u06cc\u0646\u0627\u0646\u200c\u0628\u062e\u0634\u06cc \u0645\u0639\u0642\u0648\u0644 \u0627\u0648\u0633\u062a.",
   "interpretation": "\u0628\u0627 \u063a\u0644\u0628\u0647\u0654 \u0633\u0627\u0628\u0642\u0647\u0654 \u06a9\u06cc\u0633\u062a \u062a\u062e\u0645\u062f\u0627\u0646 \u062a\u062d\u0644\u06cc\u0644\u200c\u0631\u0641\u062a\u0647 \u0648 \u062a\u062e\u0645\u062f\u0627\u0646\u200c\u0647\u0627\u06cc \u0637\u0628\u06cc\u0639\u06cc \u0641\u0639\u0644\u06cc\u060c \u0633\u0647 \u0645\u06cc\u0648\u0645 \u06a9\u0648\u0686\u06a9 \u062f\u06cc\u0648\u0627\u0631\u0647\u200c\u0627\u06cc/\u0633\u0627\u0628\u200c\u0633\u0631\u0648\u0632\u0627\u0644 \u062f\u0631 \u063a\u06cc\u0627\u0628 \u0639\u0644\u0627\u06cc\u0645 \u0645\u062b\u0644 \u0645\u0646\u0648\u0631\u0627\u0698\u06cc\u060c \u062f\u0631\u062f \u06cc\u0627 \u0627\u062b\u0631 \u0641\u0634\u0627\u0631\u06cc\u060c \u0635\u0631\u0641\u0627\u064b \u06cc\u0627\u0641\u062a\u0647\u200c\u0647\u0627\u06cc \u062a\u0635\u0627\u062f\u0641\u06cc\u200c\u0627\u0646\u062f \u0648 \u062f\u0631\u0645\u0627\u0646\u200c\u0647\u0627\u06cc \u062a\u0647\u0627\u062c\u0645\u06cc (\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u06cc\u0627 \u0645\u06cc\u0648\u0645\u06a9\u062a\u0648\u0645\u06cc) \u062a\u0648\u062c\u06cc\u0647 \u0646\u062f\u0627\u0631\u0646\u062f \u0648 OCP \u0646\u06cc\u0632 \u0628\u0631\u0627\u06cc \u0645\u06cc\u0648\u0645 \u0645\u062d\u0636 \u062f\u0631\u0645\u0627\u0646 \u0646\u06cc\u0633\u062a\u061b \u0631\u0648\u06cc\u06a9\u0631\u062f \u0645\u0646\u0627\u0633\u0628\u060c \u0645\u0634\u0627\u0647\u062f\u0647 \u0648 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0628\u0627\u0644\u06cc\u0646\u06cc-\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc\u06a9 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0639\u0644\u0627\u06cc\u0645 \u0627\u0633\u062a.",
   "reasons": ["\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u062f\u0631 \u0645\u06cc\u0648\u0645 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u06a9\u0648\u0686\u06a9 \u062f\u0631\u0645\u0627\u0646 \u0628\u06cc\u0634 \u0627\u0632 \u062d\u062f \u0627\u0633\u062a.", "\u0645\u06cc\u0648\u0645\u06a9\u062a\u0648\u0645\u06cc \u0628\u0631\u0627\u06cc \u0645\u06cc\u0648\u0645\u200c\u0647\u0627\u06cc \u062e\u0641\u06cc\u0641 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.", "\u0642\u0631\u0635 \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0628\u0631\u0627\u06cc \u0645\u06cc\u0648\u0645 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u0636\u0631\u0648\u0631\u062a\u06cc \u0646\u062f\u0627\u0631\u062f \u0648 \u0641\u0642\u0637 \u062f\u0631 \u0639\u0644\u0627\u06cc\u0645 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0641\u06a9\u0631 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a+\u0627\u0646\u062f\u0627\u0632\u0647 \u06a9\u0648\u0686\u06a9 \u06cc\u0639\u0646\u06cc \u0641\u0642\u0637 \u0646\u0638\u0627\u0631\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 63): {
   "topic": "sfhBelowBiometry",
   "lead": "\u0627\u062e\u062a\u0644\u0627\u0641 \u0642\u0627\u0628\u0644\u200c\u062a\u0648\u062c\u0647 \u0627\u0631\u062a\u0641\u0627\u0639 \u0631\u062d\u0645 \u0628\u0627 \u0633\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (\u06f2\u06f8 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631 \u0628\u0647\u200c\u062c\u0627\u06cc \u062d\u062f\u0648\u062f \u06f3\u06f2 \u062f\u0631 \u06f3\u06f2 \u0647\u0641\u062a\u0647): \u0642\u062f\u0645 \u0627\u0648\u0644 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u06cc\u0648\u0645\u062a\u0631\u06cc \u0628\u0631\u0627\u06cc \u0633\u0646\u062c\u0634 \u0631\u0634\u062f \u062c\u0646\u06cc\u0646.",
   "interpretation": "\u0633\u0646 \u0633\u0645\u0641\u06cc\u0632-\u0641\u0648\u0646\u062f\u0648\u0633 \u062f\u0631 \u0642\u0627\u0639\u062f\u0647\u0654 \u062a\u0642\u0631\u06cc\u0628\u06cc \u0628\u0627\u06cc\u062f \u0628\u0627 \u0647\u0641\u062a\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0637\u0627\u0628\u0642\u062a \u062f\u0627\u0634\u062a\u0647 \u0628\u0627\u0634\u062f (\u00b1\u06f3 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631)\u061b \u0627\u062e\u062a\u0644\u0627\u0641 \u06f4 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631\u06cc \u06cc\u0627 \u0628\u06cc\u0634\u200c\u062a\u0631 \u0647\u0634\u062f\u0627\u0631 \u0628\u0631\u0627\u06cc \u0645\u062d\u062f\u0648\u062f\u06cc\u062a \u0631\u0634\u062f \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u06cc\u0627 \u062e\u0637\u0627\u06cc \u062a\u0627\u0631\u06cc\u062e \u0627\u0633\u062a \u0648 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0645\u062a\u0648\u0627\u0644\u06cc \u0628\u0627 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc (\u0628\u06cc\u0648\u0645\u062a\u0631\u06cc+\u062a\u0639\u06cc\u06cc\u0646 \u062d\u062c\u0645 \u0645\u0627\u06cc\u0639 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9) \u0634\u0631\u0648\u0639 \u0645\u06cc\u200c\u0634\u0648\u062f \u062a\u0627 IUGR \u062a\u0641\u06a9\u06cc\u06a9 \u0634\u0648\u062f\u061b \u062f\u0627\u067e\u0644\u0631 \u0634\u0631\u06cc\u0627\u0646 \u0646\u0627\u0641\u06cc \u0645\u0631\u062d\u0644\u0647\u0654 \u0628\u0639\u062f\u06cc \u0627\u0633\u062a \u0648 \u0628\u06cc\u0648\u0641\u06cc\u0632\u06cc\u06a9\u0627\u0644 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u067e\u0633 \u0627\u0632 \u0645\u0633\u062a\u0646\u062f\u0634\u062f\u0646 \u0645\u0634\u06a9\u0644 \u0631\u0634\u062f \u06a9\u0627\u0631\u0628\u0631\u062f \u062f\u0627\u0631\u062f \u0648 \u0645\u0631\u0627\u0642\u0628\u062a \u0631\u0648\u062a\u06cc\u0646 \u062f\u0631 \u0627\u06cc\u0646 \u0627\u0646\u062f\u0627\u0632\u0647 \u062e\u0637\u0627 \u0645\u06cc\u200c\u0627\u06cc\u0633\u062a\u062f.",
   "reasons": ["\u062f\u0627\u067e\u0644\u0631 \u0634\u0631\u06cc\u0627\u0646 \u0646\u0627\u0641\u06cc \u06af\u0627\u0645 \u0628\u0639\u062f \u067e\u0633 \u0627\u0632 \u0645\u0633\u062a\u0646\u062f\u0634\u062f\u0646 IUGR \u062f\u0631 \u0628\u06cc\u0648\u0645\u062a\u0631\u06cc \u0627\u0633\u062a.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u06cc\u0648\u0645\u062a\u0631\u06cc \u0627\u0648\u0644\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u062f\u0631 \u0627\u062e\u062a\u0644\u0627\u0641 \u0627\u0631\u062a\u0641\u0627\u0639 \u0631\u062d\u0645 \u0628\u0627 \u0633\u0646 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0628\u06cc\u0648\u0641\u06cc\u0632\u06cc\u06a9\u0627\u0644 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u0628\u0631\u0627\u06cc \u067e\u0627\u06cc\u0634 \u0628\u06cc\u0645\u0627\u0631 \u0645\u0633\u062a\u0646\u062f\u0634\u062f\u0647\u0654 IUGR \u06a9\u0627\u0631\u0628\u0631\u062f \u062f\u0627\u0631\u062f \u0646\u0647 \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u0642\u062f\u0645 \u0627\u0648\u0644.", "\u0627\u062f\u0627\u0645\u0647\u0654 \u0645\u0631\u0627\u0642\u0628\u062a \u0631\u0648\u062a\u06cc\u0646 \u0627\u06cc\u0646 \u0627\u062e\u062a\u0644\u0627\u0641 \u0631\u0627 \u0646\u0627\u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f."],
  },
  (28, 64): {
   "topic": "postdatesInduceFavourable",
   "lead": "\u06f4\u06f1 \u0647\u0641\u062a\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u06af\u0632\u0627\u0631\u0634 \u06a9\u0627\u0647\u0634 \u062d\u0631\u06a9\u0627\u062a \u062c\u0646\u06cc\u0646 \u0648 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0645\u0637\u0644\u0648\u0628 (\u0622\u0645\u0627\u062f\u0647): \u0627\u0644\u0642\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u062f\u0631\u0633\u062a\u200c\u062a\u0631 \u0627\u0632 NST/BPP \u062f\u0648\u0628\u0627\u0631\u0647 \u06cc\u0627 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0628\u06cc\u200c\u062f\u0644\u06cc\u0644 \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 (\u06f4\u06f1 \u0647\u0641\u062a\u0647 \u0648 \u0628\u06cc\u0634\u200c\u062a\u0631) \u0628\u0627 \u0634\u0631\u0627\u06cc\u0637 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u06a9\u0627\u0645\u0644 (\u0646\u0631\u0645\u060c \u0642\u062f\u0627\u0645\u06cc\u060c \u0627\u0641\u0627\u0633\u0645\u0627\u0646 \u0628\u0627\u0644\u0627) \u0648 \u06af\u0632\u0627\u0631\u0634 \u0645\u0627\u062f\u0631 \u0627\u0632 \u06a9\u0627\u0647\u0634 \u062d\u0631\u06a9\u0627\u062a \u062c\u0646\u06cc\u0646 \u2014 \u06a9\u0647 \u0628\u0647\u200c\u062e\u0648\u062f\u06cc\u200c\u062e\u0648\u062f \u0647\u0634\u062f\u0627\u0631 \u0627\u0633\u062a \u2014 \u0627\u0644\u0642\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u0645\u0646\u0637\u0642\u06cc\u200c\u062a\u0631\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u0627\u0633\u062a \u0686\u0648\u0646 \u0631\u06cc\u0633\u06a9 \u0627\u062f\u0627\u0645\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0632 \u062a\u0631\u0645 \u06af\u0630\u0634\u062a\u0647 \u0627\u0633\u062a\u061b \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0648 NST \u062f\u0631 \u0627\u06cc\u0646 \u0648\u0636\u0639\u06cc\u062a \u06af\u0632\u0627\u0631\u0634\u200c\u062f\u0647\u0646\u062f\u0647\u0654 \u0648\u0636\u0639 \u0644\u062d\u0638\u0647\u200c\u0627\u06cc\u200c\u0627\u0646\u062f \u0648\u0644\u06cc \u062f\u0631 \u0645\u0646\u0637\u0642 \u06a9\u0644\u06cc\u062f\u060c \u0628\u0627 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0645\u0637\u0644\u0648\u0628 \u0646\u0628\u0627\u06cc\u062f \u062a\u0635\u0645\u06cc\u0645 \u0645\u0639\u0648\u0642 \u0634\u0648\u062f \u0648 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0628\u062f\u0648\u0646 \u0639\u0644\u062a \u0627\u0636\u0627\u0641\u0647 \u0627\u0646\u062c\u0627\u0645 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0627\u0646\u062c\u0627\u0645 NST \u0648 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0631 \u06a9\u0627\u0647\u0634 \u062d\u0631\u06a9\u0627\u062a \u0647\u0645\u0631\u0627\u0647 \u0633\u0646 \u06af\u0630\u0634\u062a\u0647 \u0648 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0645\u0637\u0644\u0648\u0628 \u0622\u0646\u200c\u0642\u062f\u0631 \u0645\u062d\u0627\u0641\u0638\u0647\u200c\u06a9\u0627\u0631\u0627\u0646\u0647 \u0646\u06cc\u0633\u062a \u06a9\u0647 \u062e\u062a\u0645 \u0631\u0627 \u0628\u0647 \u062a\u0623\u062e\u06cc\u0631 \u0628\u06cc\u0646\u062f\u0627\u0632\u062f.", "\u0627\u0644\u0642\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u0628\u0627 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0645\u0637\u0644\u0648\u0628 \u062f\u0631 \u0627\u06cc\u0646 \u0646\u0642\u0637\u0647 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633\u06cc \u0628\u062f\u0648\u0646 \u062f\u06cc\u0633\u062a\u0631\u0633 \u06cc\u0627 \u0639\u0644\u062a \u0627\u0636\u0627\u0641\u06cc \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.", "\u062f\u0631\u062e\u0648\u0627\u0633\u062a BPP \u062f\u0631 \u0634\u0631\u0627\u06cc\u0637 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0645\u0637\u0644\u0648\u0628 \u0648 \u06a9\u0627\u0647\u0634 \u062d\u0631\u06a9\u0627\u062a\u060c \u06af\u0632\u06cc\u0646\u0647\u0654 \u0645\u0631\u062c\u0639 \u0646\u06cc\u0633\u062a."],
  },
  (28, 65): {
   "topic": "hrtImmobilizationVte",
   "lead": "\u0634\u06a9\u0633\u062a\u06af\u06cc \u0644\u06af\u0646 \u0648 \u0628\u06cc\u200c\u062d\u0631\u06a9\u062a\u06cc \u0637\u0648\u0644\u0627\u0646\u06cc \u062f\u0631 \u0645\u0635\u0631\u0641\u200c\u06a9\u0646\u0646\u062f\u0647\u0654 HRT: \u0627\u0635\u0644\u0627\u062d \u0631\u06cc\u0633\u06a9 \u062a\u0631\u0648\u0645\u0628\u0648\u0622\u0645\u0628\u0648\u0644\u06cc \u0628\u0627 \u067e\u0631\u0648\u0641\u06cc\u0644\u0627\u06a9\u0633\u06cc (\u0628\u0647 \u0645\u0631\u0648\u0631 \u0628\u0627 \u067e\u0632\u0634\u06a9 \u062f\u0631\u0628\u0627\u0631\u0647\u0654 HRT \u0646\u06cc\u0632 \u062a\u0635\u0645\u06cc\u0645 \u0634\u0648\u062f).",
   "interpretation": "\u0628\u06cc\u200c\u062d\u0631\u06a9\u062a\u06cc \u067e\u0633 \u0627\u0632 \u0634\u06a9\u0633\u062a\u06af\u06cc \u0644\u06af\u0646\u060c \u062a\u0631\u0648\u0645\u0628\u0648\u0622\u0645\u0628\u0648\u0644\u06cc \u0648\u0631\u06cc\u062f\u06cc \u0631\u0627 \u0628\u0647\u200c\u0637\u0648\u0631 \u0686\u0634\u0645\u06af\u06cc\u0631\u06cc \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f \u0648 HRT \u0646\u06cc\u0632 \u0631\u06cc\u0633\u06a9 \u0627\u0641\u0632\u0648\u062f\u0647 \u0627\u0633\u062a\u061b \u062f\u0631 \u0627\u06cc\u0646 \u0634\u0631\u0627\u06cc\u0637 \u0627\u0642\u062f\u0627\u0645 \u067e\u0630\u06cc\u0631\u0641\u062a\u0647\u200c\u0634\u062f\u0647\u0654 \u0641\u0648\u0631\u06cc\u060c \u067e\u0631\u0648\u0641\u06cc\u0644\u0627\u06a9\u0633\u06cc \u062f\u0627\u0631\u0648\u06cc\u06cc-\u0645\u06a9\u0627\u0646\u06cc\u06a9\u06cc \u062a\u0631\u0648\u0645\u0628\u0648\u0622\u0645\u0628\u0648\u0644\u06cc \u0627\u0633\u062a \u0648 \u0646\u0647 \u0647\u067e\u0627\u0631\u06cc\u0646 \u062f\u0648\u0632 \u062f\u0631\u0645\u0627\u0646\u06cc \u06a9\u0647 \u0628\u0631\u0627\u06cc \u062a\u0631\u0648\u0645\u0628\u0648\u0632 \u062a\u0634\u06a9\u06cc\u0644\u200c\u0634\u062f\u0647 \u0627\u0633\u062a \u0648 \u062a\u0639\u0648\u06cc\u0642 HRT \u06cc\u0627 OCP \u0646\u06cc\u0632 \u062f\u0631 \u0627\u06cc\u0646 \u0648\u0636\u0639\u06cc\u062a \u0627\u0648\u0631\u0698\u0627\u0646\u0633\u06cc \u0646\u0627\u062f\u0631\u0633\u062a \u0627\u0633\u062a \u0648 \u00ab\u0628\u062f\u0648\u0646 \u0627\u0642\u062f\u0627\u0645\u00bb \u062f\u0631 \u0627\u06cc\u0646 \u0631\u06cc\u0633\u06a9 \u0628\u0627\u0644\u0627 \u067e\u0630\u06cc\u0631\u0641\u062a\u0646\u06cc \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u062f\u0648\u0632 \u062f\u0631\u0645\u0627\u0646\u06cc \u0647\u067e\u0627\u0631\u06cc\u0646 \u0628\u0631\u0627\u06cc \u062a\u0631\u0648\u0645\u0628\u0648\u0622\u0645\u0628\u0648\u0644\u06cc \u0627\u062b\u0628\u0627\u062a\u200c\u0634\u062f\u0647 \u0627\u0633\u062a \u0646\u0647 \u067e\u0631\u0648\u0641\u06cc\u0644\u0627\u06a9\u0633\u06cc.", "\u067e\u0631\u0648\u0641\u06cc\u0644\u0627\u06a9\u0633\u06cc \u062a\u0631\u0648\u0645\u0628\u0648\u0622\u0645\u0628\u0648\u0644\u06cc \u0627\u0642\u062f\u0627\u0645 \u062f\u0631\u0633\u062a \u062f\u0631 \u0628\u06cc\u200c\u062d\u0631\u06a9\u062a\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0642\u0637\u0639 HRT \u0648 \u0634\u0631\u0648\u0639 OCP \u062f\u0631 \u0627\u06cc\u0646 \u0632\u0645\u06cc\u0646\u0647 \u0645\u0646\u0627\u0633\u0628 \u0646\u06cc\u0633\u062a (\u0647\u0631 \u062f\u0648 \u0631\u06cc\u0633\u06a9 \u0627\u0641\u0632\u0648\u062f\u0647\u200c\u0627\u0646\u062f).", "\u0628\u062f\u0648\u0646 \u0627\u0642\u062f\u0627\u0645 \u062f\u0631 \u0631\u06cc\u0633\u06a9 \u0628\u0627\u0644\u0627\u06cc \u0628\u06cc\u200c\u062d\u0631\u06a9\u062a\u06cc \u0642\u0627\u0628\u0644\u200c\u0642\u0628\u0648\u0644 \u0646\u06cc\u0633\u062a."],
  },
  (28, 67): {
   "topic": "pyeloPersistingFeverImaging",
   "lead": "\u067e\u06cc\u0644\u0648\u0646\u0641\u0631\u06cc\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u062a\u0628 \u0645\u062f\u0627\u0648\u0645 \u0628\u06cc\u0634 \u0627\u0632 \u06f4\u06f8 \u0633\u0627\u0639\u062a \u0639\u0644\u06cc\u200c\u0631\u063a\u0645 \u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u062a\u06cc\u06a9 \u0645\u0646\u0627\u0633\u0628: \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u06a9\u0644\u06cc\u0647\u200c\u0647\u0627 \u0628\u0631\u0627\u06cc \u0631\u062f \u0622\u0628\u0633\u0647\u0654 \u06a9\u0644\u06cc\u0648\u06cc/\u067e\u06cc\u0631\u0627\u0645\u0648\u0646\u200c\u06a9\u0644\u06cc\u0647\u0654 \u06cc\u0627 \u0627\u0646\u0633\u062f\u0627\u062f.",
   "interpretation": "\u062f\u0631 \u067e\u06cc\u0644\u0648\u0646\u0641\u0631\u06cc\u062a \u062d\u0627\u062f \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0646\u062a\u0638\u0627\u0631 \u0645\u06cc\u200c\u0631\u0648\u062f \u062a\u0628 \u0638\u0631\u0641 \u06f4\u06f8-\u06f7\u06f2 \u0633\u0627\u0639\u062a \u0627\u0632 \u0634\u0631\u0648\u0639 \u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u062a\u06cc\u06a9 \u0645\u0646\u0627\u0633\u0628 \u0641\u0631\u0648\u06a9\u0634 \u06a9\u0646\u062f\u061b \u062a\u062f\u0627\u0648\u0645 \u062a\u0628 \u0628\u0647\u200c\u0645\u0639\u0646\u0627\u06cc \u0627\u0645\u06a9\u0627\u0646 \u0622\u0646\u0627\u062a\u0648\u0645\u06cc \u063a\u06cc\u0631\u0639\u0627\u062f\u06cc\u060c \u0627\u0646\u0633\u062f\u0627\u062f \u0633\u0646\u06af\u060c \u0622\u0628\u0633\u0647\u0654 \u06a9\u0644\u06cc\u0648\u06cc/\u067e\u06cc\u0631\u0627\u0645\u0648\u0646\u200c\u06a9\u0644\u06cc\u0647\u0654 \u06cc\u0627 \u0645\u0642\u0627\u0648\u0645\u062a \u0645\u06cc\u06a9\u0631\u0648\u0628\u06cc \u0627\u0633\u062a \u0648 \u0627\u0648\u0644\u06cc\u0646 \u0642\u062f\u0645 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u062a\u0635\u0648\u06cc\u0631\u06cc (\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u06a9\u0644\u06cc\u0647 \u0648 \u0645\u062c\u0627\u0631\u06cc) \u0627\u0633\u062a\u061b \u062a\u0639\u0648\u06cc\u0636 \u062a\u062c\u0631\u0628\u06cc \u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u062a\u06cc\u06a9 \u0642\u0628\u0644 \u0627\u0632 \u0628\u0631\u0631\u0633\u06cc \u0639\u0644\u0644 \u0633\u0627\u062e\u062a\u0627\u0631\u06cc \u062a\u0623\u062e\u06cc\u0631 \u0627\u0633\u062a \u0648 \u062a\u06a9\u0631\u0627\u0631 \u0622\u0632\u0645\u0627\u06cc\u0634 \u0627\u062f\u0631\u0627\u0631 \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062a\u0635\u0645\u06cc\u0645\u200c\u0633\u0627\u0632 \u0646\u06cc\u0633\u062a \u0648 \u0627\u062f\u0627\u0645\u0647\u0654 \u0647\u0645\u0627\u0646 \u062f\u0631\u0645\u0627\u0646 \u0628\u062f\u0648\u0646 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u062e\u0637\u0631 \u0633\u067e\u0633\u06cc\u0633 \u0631\u0627 \u0632\u06cc\u0627\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f.",
   "reasons": ["\u0627\u062f\u0627\u0645\u0647\u0654 \u0647\u0645\u0627\u0646 \u062f\u0631\u0645\u0627\u0646 \u0628\u062f\u0648\u0646 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0631\u06cc\u0633\u06a9 \u0622\u0628\u0633\u0647/\u0627\u0646\u0633\u062f\u0627\u062f \u0631\u0627 \u0627\u0632\u062f\u0633\u062a \u0645\u06cc\u200c\u062f\u0647\u062f.", "\u062a\u0639\u0648\u06cc\u0636 \u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u062a\u06cc\u06a9 \u0628\u062f\u0648\u0646 \u0628\u0631\u0631\u0633\u06cc \u0639\u0644\u0644 \u0633\u0627\u062e\u062a\u0627\u0631\u06cc \u06af\u0627\u0645 \u0632\u0648\u062f\u0647\u0646\u06af\u0627\u0645 \u0627\u0633\u062a.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u06a9\u0644\u06cc\u0647\u200c\u0647\u0627 \u062f\u0631 \u062a\u0628 \u0645\u062f\u0627\u0648\u0645 \u067e\u06cc\u0644\u0648\u0646\u0641\u0631\u06cc\u062a \u0627\u0642\u062f\u0627\u0645 \u0635\u062d\u06cc\u062d \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u06a9\u0631\u0627\u0631 \u0622\u0632\u0645\u0627\u06cc\u0634 \u0627\u062f\u0631\u0627\u0631 \u0628\u0647\u200c\u062e\u0648\u062f\u06cc\u200c\u062e\u0648\u062f \u062a\u0635\u0645\u06cc\u0645 \u0631\u0627 \u062a\u063a\u06cc\u06cc\u0631 \u0646\u0645\u06cc\u200c\u062f\u0647\u062f."],
  },
  (28, 68): {
   "topic": "postMolarFollow",
   "lead": "\u062d\u062a\u06cc \u067e\u0633 \u0627\u0632 \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0628\u0631\u0627\u06cc \u0645\u0648\u0644 \u06a9\u0627\u0645\u0644\u060c \u0686\u0648\u0646 \u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u062a\u0631\u0648\u0641\u0648\u0628\u0644\u0627\u0633\u062a \u06af\u0631\u062f\u0634 \u062e\u0648\u0646 \u0628\u0627\u0642\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u0646\u062f\u060c \u0686\u06a9 \u0633\u0631\u06cc BHCG \u0647\u0641\u062a\u06af\u06cc \u062a\u0627 \u0645\u0646\u0641\u06cc \u0648 \u0633\u067e\u0633 \u0637\u06cc \u062f\u0648\u0631\u0647\u0654 \u067e\u0627\u06cc\u0634 \u0644\u0627\u0632\u0645 \u0627\u0633\u062a.",
   "interpretation": "\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0631\u062d\u0645 \u0631\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f \u0648\u0644\u06cc \u0627\u0632 \u0634\u06a9\u0644\u200c\u06af\u06cc\u0631\u06cc GTN \u062f\u0631 \u0633\u0627\u06cc\u062a\u200c\u0647\u0627\u06cc \u062f\u0648\u0631 \u062c\u0644\u0648\u06af\u06cc\u0631\u06cc \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u062e\u0637\u0631 \u0639\u0648\u062f \u0628\u0647\u200c\u0648\u06cc\u0698\u0647 \u062f\u0631 \u0645\u0648\u0644 \u06a9\u0627\u0645\u0644 \u0628\u0627\u0642\u06cc \u0627\u0633\u062a\u061b \u062a\u0646\u0647\u0627 \u062a\u0633\u062a \u0645\u0624\u06cc\u062f \u0628\u0631\u0627\u06cc \u067e\u06cc\u06af\u06cc\u0631\u06cc\u060c \u062a\u06cc\u062a\u0631 BHCG (\u0647\u0641\u062a\u06af\u06cc \u062a\u0627 \u0645\u0646\u0641\u06cc \u0634\u062f\u0646 \u0648 \u0633\u067e\u0633 \u0628\u0631 \u0627\u0633\u0627\u0633 \u067e\u0631\u0648\u062a\u06a9\u0644 \u0645\u0627\u0647\u0627\u0646\u0647) \u0627\u0633\u062a\u061b \u067e\u0631\u0648\u0644\u0627\u06a9\u062a\u06cc\u0646 \u0648 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0645\u0627\u0647\u0627\u0646\u0647 \u06cc\u0627 \u0639\u062f\u0645 \u067e\u06cc\u06af\u06cc\u0631\u06cc\u060c \u0647\u06cc\u0686\u200c\u06a9\u062f\u0627\u0645 \u0642\u0627\u0639\u062f\u0647\u0654 \u067e\u0627\u06cc\u0634 \u0646\u0626\u0648\u067e\u0644\u0627\u0632\u06cc \u062a\u0631\u0648\u0641\u0648\u0628\u0644\u0627\u0633\u062a\u06cc\u06a9 \u0631\u0627 \u0631\u0639\u0627\u06cc\u062a \u0646\u0645\u06cc\u200c\u06a9\u0646\u0646\u062f.",
   "reasons": ["\u0686\u06a9 BHCG \u0647\u0641\u062a\u06af\u06cc \u0633\u062a\u0648\u0646 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u067e\u0633 \u0627\u0632-\u0645\u0648\u0644 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u067e\u0631\u0648\u0644\u0627\u06a9\u062a\u06cc\u0646 \u062f\u0631 \u067e\u0627\u06cc\u0634 \u0628\u06cc\u0645\u0627\u0631\u06cc \u062a\u0631\u0648\u0641\u0648\u0628\u0644\u0627\u0633\u062a\u06cc\u06a9 \u0646\u0642\u0634 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0645\u0627\u0647\u0627\u0646\u0647 \u062c\u0627\u06cc \u062a\u06cc\u062a\u0631 BHCG \u0631\u0627 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u062f.", "\u0686\u0634\u0645\u200c\u067e\u0648\u0634\u06cc \u0627\u0632 \u067e\u0627\u06cc\u0634 \u062f\u0631 \u0645\u0648\u0644 \u06a9\u0627\u0645\u0644 \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u062e\u0637\u0631 \u0628\u0627\u0644\u0627\u06cc GTN \u062e\u0637\u0631\u0646\u0627\u06a9 \u0627\u0633\u062a."],
  },
  (28, 69): {
   "topic": "bvDiagnosis",
   "lead": "\u062a\u0631\u0634\u062d \u0647\u0645\u06af\u0646 \u0633\u0641\u06cc\u062f + pH>\u06f4\u066b\u06f5 + \u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u0633\u0631\u0646\u062e (clue) \u0628\u0627\u0644\u0627\u06cc \u06f2\u06f0\u066a \u062f\u0631 \u0645\u06cc\u06a9\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc: \u062a\u0634\u062e\u06cc\u0635 \u0628\u0627\u0644\u06cc\u0646\u06cc \u0648\u0627\u0698\u06cc\u0646\u0648\u0632 \u0628\u0627\u06a9\u062a\u0631\u06cc\u0627\u0644 (BV).",
   "interpretation": "\u0645\u0639\u06cc\u0627\u0631 \u0622\u0645\u0633\u0644 \u0628\u0631\u0627\u06cc BV \u062f\u0633\u062a\u200c\u06a9\u0645 \u0633\u0647 \u0645\u0648\u0631\u062f \u0627\u0632 \u0686\u0647\u0627\u0631: \u062a\u0631\u0634\u062d \u0633\u0641\u06cc\u062f \u0647\u0645\u06af\u0646 \u0686\u0633\u0628\u06cc\u062f\u0647 \u0628\u0647 \u062f\u06cc\u0648\u0627\u0631\u0647\u0654 \u0648\u0627\u0698\u0646\u060c pH>\u06f4\u066b\u06f5\u060c \u0628\u0648\u06cc \u0645\u0627\u0647\u06cc \u0628\u0627 \u0627\u0636\u0627\u0641\u0647\u200c\u0634\u062f\u0646 \u0647\u06cc\u062f\u0631\u0648\u06a9\u0633\u06cc\u062f \u067e\u062a\u0627\u0633\u06cc\u0645 \u0648 \u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u0633\u0631\u0646\u062e (clue) \u062f\u0631 \u0628\u06cc\u0634 \u0627\u0632 \u06f2\u06f0\u066a \u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u0627\u067e\u06cc\u062a\u0644\u06cc\u0627\u0644\u061b \u062f\u0631 \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631 \u062d\u062f\u0627\u0642\u0644 \u0633\u0647 \u0645\u0639\u06cc\u0627\u0631 \u0635\u0631\u0627\u062d\u062a\u0627\u064b \u0631\u0639\u0627\u06cc\u062a \u0634\u062f\u0647 \u0648 \u062a\u0634\u062e\u06cc\u0635 \u0628\u0627\u0644\u06cc\u0646\u06cc BV \u0627\u0633\u062a\u061b \u06a9\u0627\u0646\u062f\u06cc\u062f\u06cc\u0627\u0632 pH \u0646\u0631\u0645\u0627\u0644 \u0648 \u062a\u0631\u0634\u062d \u067e\u0646\u06cc\u0631\u06cc\u200c\u0645\u0627\u0646\u0646\u062f \u062f\u0627\u0631\u062f\u060c \u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627\u0633 \u0633\u0644\u0648\u0644 clue \u0646\u062f\u0627\u0631\u062f \u0648 \u0648\u0627\u0698\u06cc\u0646\u06cc\u062a \u0622\u062a\u0631\u0648\u0641\u06cc\u06a9 \u062f\u0631 \u0632\u0646\u0627\u0646 \u06f4\u06f0 \u0633\u0627\u0644\u0647\u0654 \u067e\u0631\u06cc\u200c\u0645\u0646\u0648\u067e\u0648\u0632\u0627\u0644 \u0628\u0627 \u0627\u06cc\u0646 \u06cc\u0627\u0641\u062a\u0647\u200c\u0647\u0627 \u062f\u0631 \u0635\u062f\u0631 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u06a9\u0627\u0646\u062f\u06cc\u062f\u06cc\u0627\u0632 \u0628\u0627 \u062a\u0631\u0634\u062d \u067e\u0646\u06cc\u0631\u06cc \u0648 pH \u0646\u0631\u0645\u0627\u0644 (\u06f4\u066b\u06f5 \u06cc\u0627 \u06a9\u0645\u200c\u062a\u0631) \u0645\u06cc\u200c\u0622\u06cc\u062f \u0646\u0647 \u0633\u0644\u0648\u0644 \u0633\u0631\u0646\u062e.", "\u0627\u06cc\u0646 \u0633\u0647 \u0645\u0639\u06cc\u0627\u0631 \u0645\u0639\u06cc\u0627\u0631 \u0622\u0645\u0633\u0644 \u0631\u0627 \u0628\u0631\u0627\u06cc BV \u062a\u0623\u0645\u06cc\u0646 \u0645\u06cc\u200c\u06a9\u0646\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627\u0633 \u0628\u0627 \u062a\u0631\u0634\u062d \u0622\u0628\u06a9\u06cc \u0648 \u06a9\u0641\u200c\u0622\u0644\u0648\u062f \u0648 pH \u0628\u0627\u0644\u0627 \u0648\u0644\u06cc \u0633\u0644\u0648\u0644 \u0633\u0631\u0646\u062e \u0646\u062f\u0627\u0631\u062f \u0648 \u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627\u0633 \u0645\u062a\u062d\u0631\u06a9 \u062f\u0631 \u0648\u062a\u200c\u0645\u0648\u0646\u062a \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0648\u0627\u0698\u06cc\u0646\u06cc\u062a \u0622\u062a\u0631\u0648\u0641\u06cc\u06a9 \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u0628\u0627 \u0627\u06cc\u0646 \u0648\u06cc\u0698\u06af\u06cc\u200c\u0647\u0627 \u0645\u0637\u0631\u062d \u0646\u06cc\u0633\u062a."],
  },
  (28, 70): {
   "topic": "aisSyndrome",
   "lead": "46XY + \u0628\u0644\u0648\u063a \u067e\u0633\u062a\u0627\u0646\u06cc \u0637\u0628\u06cc\u0639\u06cc + \u0645\u0648\u0647\u0627\u06cc \u0634\u0631\u0645\u06af\u0627\u0647\u06cc \u0628\u0633\u06cc\u0627\u0631 \u06a9\u0645 + \u0648\u0627\u0698\u0646 \u0628\u0633\u062a\u0647\u0654 \u06a9\u0648\u062a\u0627\u0647 + \u062a\u0648\u062f\u0647\u0654 \u062f\u0648\u0637\u0631\u0641\u0647 \u062f\u0631 \u06a9\u0627\u0646\u0627\u0644 \u0627\u06cc\u0646\u06af\u0648\u06cc\u0646\u0627\u0644: \u0633\u0646\u062f\u0631\u0645 \u0646\u0628\u0648\u062f \u062d\u0633\u0627\u0633\u06cc\u062a \u0628\u0647 \u0622\u0646\u062f\u0631\u0648\u0698\u0646 (AIS).",
   "interpretation": "\u062f\u0631 \u0633\u0646\u062f\u0631\u0645 \u0639\u062f\u0645 \u062d\u0633\u0627\u0633\u06cc\u062a \u0628\u0647 \u0622\u0646\u062f\u0631\u0648\u0698\u0646 (\u0628\u0627 \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e 46XY) \u06af\u06cc\u0631\u0646\u062f\u0647\u0654 \u0622\u0646\u062f\u0631\u0648\u0698\u0646 \u06a9\u0627\u0631 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u062a\u0633\u062a\u0648\u0633\u062a\u0631\u0648\u0646 \u0628\u0627\u0644\u0627 \u0628\u0647 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u062a\u0628\u062f\u06cc\u0644 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0628\u0644\u0648\u063a \u067e\u0633\u062a\u0627\u0646\u06cc \u0637\u0628\u06cc\u0639\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f \u0648\u0644\u06cc \u0645\u0648\u0647\u0627\u06cc \u0648\u0627\u0628\u0633\u062a\u0647 \u0628\u0647 \u0622\u0646\u062f\u0631\u0648\u0698\u0646 (\u0632\u06cc\u0631\u0628\u063a\u0644/\u0634\u0631\u0645\u06af\u0627\u0647\u06cc) \u0628\u0633\u06cc\u0627\u0631 \u06a9\u0645 \u0627\u0633\u062a\u060c \u0648\u0627\u0698\u0646 \u0628\u0647\u200c\u0635\u0648\u0631\u062a \u06a9\u0648\u0631 \u0627\u0646\u062a\u0647\u0627\u06cc\u06cc \u0627\u0633\u062a \u0648 \u062a\u0648\u062f\u0647\u200c\u0647\u0627\u06cc \u0627\u06cc\u0646\u06af\u0648\u06cc\u0646\u0627\u0644 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u06cc\u0636\u0647\u200c\u0647\u0627\u06cc \u067e\u0627\u06cc\u06cc\u0646 \u0646\u06cc\u0627\u0645\u062f\u0647\u200c\u0627\u0646\u062f\u061b \u0622\u0698\u0646\u0632\u06cc \u0645\u0648\u0644\u0631\u06cc\u0646 (MRKH) \u0628\u0627 46XX \u0645\u06cc\u200c\u0622\u06cc\u062f\u060c \u062a\u0631\u0646\u0631 \u0628\u0627 45X \u0648 \u062a\u0648\u062f\u0647\u0654 \u0627\u06cc\u0646\u06af\u0648\u06cc\u0646\u0627\u0644 \u0646\u062f\u0627\u0631\u062f \u0648 \u0633\u0646\u062f\u0631\u0645 Swyer \u0628\u0627 \u0628\u0644\u0648\u063a \u067e\u0633\u062a\u0627\u0646\u06cc \u0645\u0639\u0645\u0648\u0644 \u0648 \u062a\u0648\u062f\u0647\u0654 \u062a\u062e\u0645\u062f\u0627\u0646\u06cc \u0627\u06cc\u0646\u06af\u0648\u06cc\u0646\u0627\u0644\u06cc \u0647\u0645\u0631\u0627\u0647 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0627\u06cc\u0646 \u062f\u0627\u062f\u0647\u200c\u0647\u0627 \u062f\u0642\u06cc\u0642\u0627\u064b \u0628\u0627 AIS \u0633\u0627\u0632\u06af\u0627\u0631\u0646\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0622\u0698\u0646\u0632\u06cc \u0645\u0648\u0644\u0631\u06cc\u0646-\u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0628\u0627 46XX \u0645\u06cc\u200c\u0622\u06cc\u062f \u0646\u0647 46XY.", "\u062a\u0631\u0646\u0631 \u0628\u0627 45X \u0648 \u0628\u062f\u0648\u0646 \u062a\u0648\u062f\u0647\u0654 \u0627\u06cc\u0646\u06af\u0648\u06cc\u0646\u0627\u0644 \u062f\u0648\u0637\u0631\u0641\u0647 \u0645\u06cc\u200c\u0622\u06cc\u062f.", "Swyer \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u062a\u0648\u062f\u0647\u0654 \u062f\u0648\u0637\u0631\u0641\u0647 \u062f\u0631 \u06a9\u0627\u0646\u0627\u0644 \u0627\u06cc\u0646\u06af\u0648\u06cc\u0646\u0627\u0644 \u0646\u062f\u0627\u0631\u062f \u0648 \u0628\u0644\u0648\u063a \u067e\u0633\u062a\u0627\u0646\u06cc \u0622\u0646 \u0646\u0627\u0642\u0635 \u0627\u0633\u062a."],
  },
  (28, 71): {
   "topic": "epRiskStrongest",
   "lead": "\u062f\u0631 \u0645\u06cc\u0627\u0646 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a\u060c \u0642\u0648\u06cc\u200c\u062a\u0631\u06cc\u0646 \u0639\u0627\u0645\u0644 \u062e\u0637\u0631 \u0628\u0631\u0627\u06cc EP (\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062e\u0627\u0631\u062c\u200c\u0631\u062d\u0645\u06cc) \u0628\u0633\u062a\u0646 \u0644\u0648\u0644\u0647 (\u0644\u06cc\u06af\u0627\u0633\u06cc\u0648\u0646 \u0644\u0648\u0644\u0647) \u0627\u0633\u062a.",
   "interpretation": "\u0647\u0631 \u0686\u0647\u0627\u0631 \u0645\u0648\u0631\u062f \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u0646\u062f \u0646\u0642\u0634 \u062f\u0627\u0634\u062a\u0647 \u0628\u0627\u0634\u0646\u062f\u061b \u0627\u0645\u0627 \u0628\u0633\u062a\u0646 \u0644\u0648\u0644\u0647 (\u0627\u0633\u062a\u0631\u06cc\u0644\u06cc\u0632\u0627\u0633\u06cc\u0648\u0646) \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u0627\u06a9\u0627\u0645\u06cc\u060c \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u200c\u0647\u0627\u06cc \u0628\u0639\u062f\u06cc \u0631\u0627 \u062a\u0627 \u062d\u062f \u0632\u06cc\u0627\u062f\u06cc \u0628\u0647\u200c\u0635\u0648\u0631\u062a \u062e\u0627\u0631\u062c\u200c\u0631\u062d\u0645\u06cc \u0646\u0634\u0627\u0646 \u0645\u06cc\u200c\u062f\u0647\u062f \u0632\u06cc\u0631\u0627 \u0647\u0631 \u0627\u062a\u0635\u0627\u0644 \u0645\u062c\u062f\u062f\u060c \u062a\u0627\u062e\u06cc\u0631 \u062d\u0631\u06a9\u062a \u062a\u062e\u0645 \u0648 \u0627\u0646\u0633\u062f\u0627\u062f \u0627\u06cc\u062c\u0627\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 OR \u0634\u0646\u0627\u062e\u062a\u0647\u200c\u0634\u062f\u0647\u0654 \u0622\u0646 \u0628\u0631\u0627\u06cc EP \u0628\u0633\u06cc\u0627\u0631 \u0628\u0627\u0644\u0627\u0633\u062a\u061b \u0633\u06cc\u06af\u0627\u0631 \u0628\u0627 \u0627\u062b\u0631 \u0645\u0632\u0645\u0646 \u0628\u0631 \u0644\u0648\u0644\u0647 \u0627\u062b\u0631 \u0646\u0633\u0628\u06cc \u06a9\u0645\u062a\u0631\u06cc \u062f\u0627\u0631\u062f \u0648 \u062f\u0648\u0634 \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0648 \u062a\u0639\u062f\u0627\u062f \u067e\u0627\u0631\u062a\u0646\u0631 \u0627\u0632 \u0631\u0627\u0647 \u0639\u0641\u0648\u0646\u062a/\u0627\u0644\u062a\u0647\u0627\u0628 \u0644\u0648\u0644\u0647 \u0627\u062b\u0631 \u0645\u062a\u0648\u0633\u0637\u06cc \u062f\u0627\u0631\u0646\u062f \u0627\u0645\u0627 \u0648\u0632\u0646 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u06cc\u0646 \u067e\u0631\u0633\u0634 \u0628\u0627 \u0644\u06cc\u06af\u0627\u0633\u06cc\u0648\u0646 \u0627\u0633\u062a.",
   "reasons": ["\u0633\u06cc\u06af\u0627\u0631 \u0639\u0627\u0645\u0644 \u062e\u0637\u0631 \u0645\u0624\u062b\u0631 \u0627\u0645\u0627 \u0648\u0632\u0646 \u0622\u0646 \u0627\u0632 \u0644\u06cc\u06af\u0627\u0633\u06cc\u0648\u0646 \u06a9\u0645\u200c\u062a\u0631 \u0627\u0633\u062a.", "\u0628\u0633\u062a\u0646 \u0644\u0648\u0644\u0647 \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u0627\u06a9\u0627\u0645\u06cc \u0642\u0648\u06cc\u200c\u062a\u0631\u06cc\u0646 \u0639\u0627\u0645\u0644 \u062e\u0637\u0631 EP \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062f\u0648\u0634 \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0627\u062b\u0631 \u0636\u0639\u06cc\u0641\u200c\u062a\u0631\u06cc \u0627\u0632 \u0631\u0627\u0647 \u0639\u0641\u0648\u0646\u062a \u062f\u0627\u0631\u062f.", "\u062a\u0639\u062f\u0627\u062f \u067e\u0627\u0631\u062a\u0646\u0631 \u0627\u062b\u0631 \u063a\u06cc\u0631\u0645\u0633\u062a\u0642\u06cc\u0645 \u062f\u0627\u0631\u062f \u0648 \u0627\u0632 \u0648\u0632\u0646 \u06a9\u0644\u06cc\u062f\u06cc\u200c\u062a\u0631 \u0646\u0633\u0628\u062a \u0628\u0647 \u0644\u0648\u0644\u0647\u200c\u0628\u0633\u062a \u06a9\u0645 \u0627\u0633\u062a."],
  },
  (28, 72): {
   "topic": "earlyPregSerialHcg",
   "lead": "\u062a\u0623\u062e\u06cc\u0631 \u0645\u0646\u0633 \u0628\u0627 \u062a\u0633\u062a \u0645\u062b\u0628\u062a \u0648 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u063a\u06cc\u0631\u062a\u0634\u062e\u06cc\u0635\u06cc \u0628\u0631\u0627\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc: \u0642\u062f\u0645 \u0645\u0646\u0637\u0642\u06cc \u0686\u06a9 \u0633\u0631\u06cc BHCG\u060c \u0646\u0647 \u0627\u0642\u062f\u0627\u0645 \u062a\u0647\u0627\u062c\u0645\u06cc \u06cc\u0627 \u0635\u0631\u0641 \u062a\u06a9\u0631\u0627\u0631 \u0632\u0648\u062f\u0647\u0646\u06af\u0627\u0645 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc.",
   "interpretation": "\u0648\u0642\u062a\u06cc \u062a\u0633\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u062b\u0628\u062a \u0627\u0633\u062a \u0648\u0644\u06cc \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0647\u0646\u0648\u0632 \u0648\u062c\u0648\u062f \u0633\u0627\u06a9 \u0631\u0627 \u0646\u0645\u06cc\u200c\u0628\u06cc\u0646\u062f\u060c \u06cc\u0627 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0633\u06cc\u0627\u0631 \u0627\u0648\u0644\u06cc\u0647 \u0627\u0633\u062a \u06cc\u0627 EP\u061b \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0631\u0648\u0646\u062f BHCG \u0686\u0627\u0631\u0686\u0648\u0628 \u062a\u0635\u0645\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062f\u0647\u062f (\u0627\u06af\u0631 \u0628\u0647 \u0622\u0633\u062a\u0627\u0646\u0647\u0654 \u0646\u0627\u062d\u06cc\u0647\u0654 \u062a\u0641\u06a9\u06cc\u06a9\u06cc \u0628\u0631\u0633\u062f \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0645\u062c\u062f\u062f \u0645\u0639\u0646\u0627\u062f\u0627\u0631 \u0627\u0633\u062a \u0648 \u0627\u06af\u0631 \u067e\u0644\u0627\u062a\u0648 \u06cc\u0627 \u06a9\u0627\u0647\u0634 \u0628\u06cc\u0627\u0628\u062f \u0645\u0633\u06cc\u0631 \u0645\u062a\u0641\u0627\u0648\u062a \u0627\u0633\u062a)\u061b \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u062c\u0627\u06cc\u06af\u0627\u0647 \u0646\u062f\u0627\u0631\u062f \u0648 \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062a\u0647\u0627\u062c\u0645\u06cc \u0627\u0633\u062a \u0648 \u062a\u06a9\u0631\u0627\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u06f4\u06f8 \u0633\u0627\u0639\u062a \u0628\u0639\u062f \u0628\u062f\u0648\u0646 \u0645\u0631\u062c\u0639 BHCG \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0647\u0646\u0648\u0632 \u063a\u06cc\u0631\u062a\u0634\u062e\u06cc\u0635\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f.",
   "reasons": ["\u0686\u06a9 \u0633\u0631\u06cc BHCG \u0642\u062f\u0645 \u0645\u0646\u0637\u0642\u06cc \u0628\u0639\u062f\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u062a\u0647\u0627\u062c\u0645\u06cc \u0648 \u0632\u0648\u062f \u0627\u0633\u062a.", "\u062a\u06a9\u0631\u0627\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u06f4\u06f8 \u0633\u0627\u0639\u062a \u0628\u0639\u062f \u0628\u062f\u0648\u0646 \u0645\u0631\u062c\u0639 \u062a\u06cc\u062a\u0631 BHCG \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0647\u0646\u0648\u0632 \u063a\u06cc\u0631\u0642\u0637\u0639\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f.", "\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0641\u0642\u0637 \u062f\u0631 \u0628\u062f\u062a\u0631\u0634\u062f\u0646 \u06cc\u0627 \u06cc\u0627\u0641\u062a\u0647\u200c\u0647\u0627\u06cc \u062e\u0637\u0631 \u0622\u063a\u0627\u0632 \u0645\u06cc\u200c\u0634\u0648\u062f."],
  },
  (28, 73): {
   "topic": "gdmEarlyScreen",
   "lead": "\u0628\u06cc\u0645\u0627\u0631 \u0628\u0627 \u0641\u0627\u06a9\u062a\u0648\u0631 \u062e\u0637\u0631 \u062f\u06cc\u0627\u0628\u062a \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc: \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u062f\u0631 \u0647\u0645\u06cc\u0646 \u0648\u06cc\u0632\u06cc\u062a (\u0628\u0647\u200c\u0635\u0648\u0631\u062a \u062f\u0648\u0645\u0631\u062d\u0644\u0647\u200c\u0627\u06cc \u0628\u0627 \u062a\u0633\u062a \u06f5\u06f0 \u06af\u0631\u0645\u06cc \u06cc\u06a9\u200c\u0633\u0627\u0639\u062a\u0647) \u0634\u0631\u0648\u0639 \u0634\u0648\u062f\u060c \u0646\u0647 \u062f\u0631 \u06f2\u06f4 \u0647\u0641\u062a\u0647.",
   "interpretation": "\u0648\u062c\u0648\u062f \u0641\u0627\u06a9\u062a\u0648\u0631\u0647\u0627\u06cc \u062e\u0637\u0631 (\u0633\u0627\u0628\u0642\u0647\u0654 \u062e\u0627\u0646\u0648\u0627\u062f\u06af\u06cc \u062f\u0631\u062c\u0647\u0654 \u06cc\u06a9 \u062f\u06cc\u0627\u0628\u062a\u060c \u0633\u0627\u0628\u0642\u0647\u0654 GDM\u060c \u0686\u0627\u0642\u06cc \u0648...) \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0632\u0648\u062f\u0647\u0646\u06af\u0627\u0645 \u0631\u0627 \u062f\u0631 \u0648\u06cc\u0632\u06cc\u062a \u0627\u0648\u0644 \u062a\u0648\u062c\u06cc\u0647 \u0645\u06cc\u200c\u06a9\u0646\u062f\u061b \u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u0627\u06cc\u0631\u0627\u0646\u06cc \u062f\u0648\u0645\u0631\u062d\u0644\u0647\u200c\u0627\u06cc \u06f5\u06f0 \u06af\u0631\u0645\u06cc (GCT) \u062f\u0631 \u0648\u06cc\u0632\u06cc\u062a \u0627\u0648\u0644 \u0628\u0631\u0627\u06cc \u0627\u0641\u0631\u0627\u062f \u067e\u0631\u062e\u0637\u0631 \u067e\u06cc\u0634\u200c\u0628\u06cc\u0646\u06cc \u0634\u062f\u0647 \u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u0628\u0627\u0644\u0627 \u0628\u0648\u062f\u0646 \u0628\u0647 \u06f1\u06f0\u06f0 \u06af\u0631\u0645\u06cc \u0633\u0647\u200c\u0633\u0627\u0639\u062a\u0647 \u0645\u06cc\u200c\u0631\u0633\u062f \u0648 \u062f\u0631 \u0647\u0641\u062a\u0647\u0654 \u06f2\u06f4-\u06f2\u06f8 \u0646\u06cc\u0632 \u0628\u0631\u0627\u06cc \u0647\u0645\u0647 (\u062d\u062a\u06cc \u0627\u0641\u0631\u0627\u062f \u0628\u0627 \u0646\u062a\u06cc\u062c\u0647\u0654 \u0637\u0628\u06cc\u0639\u06cc) \u062a\u06a9\u0631\u0627\u0631 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 GCT \u06f5\u06f0 \u06af\u0631\u0645\u06cc \u062f\u0631 \u0647\u0645\u06cc\u0646 \u0648\u06cc\u0632\u06cc\u062a \u0627\u0644\u06af\u0648\u06cc \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a \u0648 \u0627\u0646\u062a\u0638\u0627\u0631 \u062a\u0627 \u06f2\u06f4 \u0647\u0641\u062a\u0647 \u062e\u0637\u0631 \u0631\u0627 \u0645\u06cc\u200c\u067e\u0630\u06cc\u0631\u062f.",
   "reasons": ["GTT \u06f1\u06f0\u06f0 \u06af\u0631\u0645\u06cc \u062f\u0631 \u0648\u06cc\u0632\u06cc\u062a \u0627\u0648\u0644 \u0641\u0642\u0637 GCT \u0645\u062b\u0628\u062a \u0631\u0627 \u062a\u0623\u06cc\u06cc\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f.", "GCT \u06f5\u06f0 \u06af\u0631\u0645\u06cc \u06f1\u06f1 \u0647\u0641\u062a\u0647 \u062f\u0631 \u0641\u0631\u062f \u067e\u0631\u062e\u0637\u0631 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u0646\u062a\u0638\u0627\u0631 \u062a\u0627 \u06f2\u06f4 \u0647\u0641\u062a\u0647 \u062f\u0631 \u067e\u0631\u062e\u0637\u0631 \u0645\u0646\u0627\u0633\u0628 \u0646\u06cc\u0633\u062a \u0648 \u0647\u0645\u06cc\u0646\u200c\u062c\u0627 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u062f\u0631\u0633\u062a \u0627\u0633\u062a.", "GCT \u06f5\u06f0 \u06af\u0631\u0645\u06cc \u062f\u0631 \u06f2\u06f4 \u0647\u0641\u062a\u0647 \u062c\u0627\u06cc \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0632\u0648\u062f \u062f\u0631 \u067e\u0631\u062e\u0637\u0631 \u0631\u0627 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u062f."],
  },
  (28, 74): {
   "topic": "herpesPregTreatment",
   "lead": "\u0636\u0627\u06cc\u0639\u0627\u062a \u0648\u0632\u06cc\u06a9\u0648\u0644\u0631 \u0645\u062a\u0639\u062f\u062f \u0648 \u062f\u0631\u062f\u0646\u0627\u06a9 \u0698\u0646\u06cc\u062a\u0627\u0644 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (\u06f3\u06f2 \u0647\u0641\u062a\u0647): \u0622\u0633\u06cc\u06a9\u0644\u0648\u06cc\u0631 \u062e\u0648\u0631\u0627\u06a9\u06cc \u0628\u0631\u0627\u06cc \u0641\u0627\u0632 \u062d\u0627\u062f (\u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u0644\u0632\u0648\u0645 \u0633\u0631\u06a9\u0648\u0628 \u0627\u0648\u0627\u062e\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc).",
   "interpretation": "\u0647\u0631\u067e\u0633 \u0633\u06cc\u0645\u067e\u0644\u06a9\u0633 \u0698\u0646\u06cc\u062a\u0627\u0644 \u062d\u0627\u062f \u0628\u0627 \u0636\u0627\u06cc\u0639\u0627\u062a \u0648\u0632\u06cc\u06a9\u0648\u0644\u0631 \u062f\u0631\u062f\u0646\u0627\u06a9 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u0622\u0633\u06cc\u06a9\u0644\u0648\u06cc\u0631 \u062e\u0648\u0631\u0627\u06a9\u06cc (\u06cc\u0627 \u0648\u0627\u0644\u0627\u0633\u06cc\u06a9\u0644\u0648\u0648\u06cc\u0631) \u0628\u0627 \u062f\u0648\u0632 \u06a9\u0627\u0645\u0644 \u062f\u0648\u0631\u0647 \u062f\u0631\u0645\u0627\u0646 \u0645\u06cc\u200c\u0634\u0648\u062f \u062a\u0627 \u0637\u0648\u0644 \u0648 \u0634\u062f\u062a \u062d\u0645\u0644\u0647 \u06a9\u0645 \u0634\u0648\u062f \u0648 \u062e\u0637\u0631 \u0639\u0648\u062f \u062f\u0631 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u06cc\u0627\u0632 \u0632\u0645\u06cc\u0646\u0647\u0654 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0641\u0631\u0627\u0647\u0645 \u0634\u0648\u062f\u061b \u0641\u0627\u0645\u0633\u06cc\u06a9\u0644\u0648\u06cc\u0631 \u062f\u0627\u062f\u0647\u0654 \u06a9\u0645\u062a\u0631\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0627\u0631\u062f\u060c \u067e\u0646\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646 \u0628\u0631\u0627\u06cc HSV \u0646\u0627\u06a9\u0627\u0631\u0622\u0645\u062f \u0627\u0633\u062a \u0648 \u0632\u06cc\u062f\u0648\u0648\u062f\u06cc\u0646 \u062c\u0632\u0648 \u062f\u0631\u0645\u0627\u0646 HIV \u0627\u0633\u062a \u0646\u0647 HSV.",
   "reasons": ["\u0641\u0627\u0645\u0633\u06cc\u06a9\u0644\u0648\u06cc\u0631 \u06af\u0632\u06cc\u0646\u0647\u0654 \u0645\u0639\u062a\u0628\u0631 \u0627\u0633\u062a \u0648\u0644\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0622\u0633\u06cc\u06a9\u0644\u0648\u06cc\u0631 \u062f\u0627\u062f\u0647 \u0628\u06cc\u0634\u200c\u062a\u0631 \u062f\u0627\u0631\u062f \u0648 \u0627\u0646\u062a\u062e\u0627\u0628 \u0627\u0648\u0644 \u0627\u0633\u062a.", "\u0632\u06cc\u062f\u0648\u0648\u062f\u06cc\u0646 \u062c\u0632\u0648 \u062f\u0631\u0645\u0627\u0646 HIV \u0627\u0633\u062a \u0648 \u062f\u0631 \u062f\u0631\u0645\u0627\u0646 HSV \u06a9\u0627\u0631\u0628\u0631\u062f\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u067e\u0646\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646 \u0628\u0631\u0627\u06cc \u0639\u0641\u0648\u0646\u062a \u0648\u06cc\u0631\u0648\u0633\u06cc \u0647\u0631\u067e\u0633 \u0627\u062b\u0631\u06cc \u0646\u062f\u0627\u0631\u062f \u0648 \u062f\u0631\u0645\u0627\u0646\u06cc \u0646\u06cc\u0633\u062a.", "\u0622\u0633\u06cc\u06a9\u0644\u0648\u06cc\u0631 \u062e\u0648\u0631\u0627\u06a9\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0645\u0646 \u0648 \u0645\u0624\u06cc\u062f \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 75): {
   "topic": "ocpCancerEffects",
   "lead": "\u0642\u0631\u0635\u200c\u0647\u0627\u06cc \u062a\u0631\u06a9\u06cc\u0628\u06cc \u062e\u0648\u0631\u0627\u06a9\u06cc \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0648 \u062a\u062e\u0645\u062f\u0627\u0646 \u0631\u0627 \u06a9\u0627\u0647\u0634 \u0645\u06cc\u200c\u062f\u0647\u0646\u062f (\u062d\u0641\u0627\u0638\u062a \u0645\u0627\u0646\u062f\u06af\u0627\u0631) \u0648 \u0631\u0648\u06cc \u0628\u0631\u0633\u062a/\u0633\u0631\u0648\u06cc\u06a9\u0633 \u0627\u062b\u0631 \u062d\u0641\u0627\u0638\u062a\u06cc \u0646\u062f\u0627\u0631\u0646\u062f.",
   "interpretation": "\u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u062d\u0636\u0648\u0631 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646\u060c OCP \u0627\u0632 \u062a\u062d\u0631\u06cc\u06a9 \u0628\u062f\u0648\u0646 \u0645\u0639\u0627\u062f\u0644 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0628\u0631 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062c\u0644\u0648\u06af\u06cc\u0631\u06cc \u0648 \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0631\u0627 \u0628\u0647\u200c\u0637\u0648\u0631 \u0645\u0627\u0646\u062f\u06af\u0627\u0631 \u06a9\u0627\u0647\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u0627\u0632 \u0637\u0631\u06cc\u0642 \u0633\u0631\u06a9\u0648\u0628 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u0627\u067e\u06cc\u062a\u0644\u06cc\u0627\u0644 \u062a\u062e\u0645\u062f\u0627\u0646 \u0631\u0627 \u0646\u06cc\u0632 \u062d\u062f\u0648\u062f \u06f4\u06f0-\u06f5\u06f0\u066a \u06a9\u0645 \u0645\u06cc\u200c\u06a9\u0646\u062f\u061b \u0627\u06cc\u0646 \u0627\u062b\u0631 \u062d\u0641\u0627\u0638\u062a\u06cc \u0633\u0627\u0644\u200c\u0647\u0627 \u067e\u0633 \u0627\u0632 \u0642\u0637\u0639 \u0628\u0627\u0642\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f \u0648 \u062f\u0631 \u0628\u0631\u0627\u0628\u0631 \u0628\u0631\u0633\u062a (\u062d\u062a\u06cc \u0631\u06cc\u0633\u06a9 \u06a9\u0648\u0686\u06a9\u06cc \u06af\u0632\u0627\u0631\u0634 \u0634\u062f\u0647) \u0648 \u0633\u0631\u0648\u06cc\u06a9\u0633/\u0631\u0648\u062f\u0647\u0654 \u0628\u0632\u0631\u06af \u062f\u0631 \u0627\u06cc\u0646 \u0686\u0627\u0631\u0686\u0648\u0628 \u06af\u0641\u062a\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0628\u0631\u0633\u062a \u062d\u062a\u06cc \u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u0631\u06cc\u0633\u06a9 \u06a9\u0648\u0686\u06a9\u06cc \u0628\u0627 OCP \u062f\u0627\u0634\u062a\u0647 \u0628\u0627\u0634\u062f \u0648 \u062d\u0641\u0627\u0638\u062a\u06cc \u0646\u06cc\u0633\u062a.", "\u0622\u0646\u062f\u0648\u0645\u062a\u0631+\u062a\u062e\u0645\u062f\u0627\u0646 \u062f\u0648 \u0633\u0631\u0637\u0627\u0646\u0650 \u062f\u0627\u0631\u0627\u06cc \u0627\u062b\u0631 \u062d\u0641\u0627\u0638\u062a\u06cc \u0645\u0624\u06cc\u062f \u0628\u0627 OCP\u200c\u0627\u0646\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0631\u0648\u06cc\u06a9\u0633/\u0631\u0648\u062f\u0647\u0654 \u0628\u0632\u0631\u06af \u062c\u0641\u062a \u062d\u0641\u0627\u0638\u062a\u06cc \u0645\u062a\u0639\u0627\u0631\u0641 OCP \u0646\u06cc\u0633\u062a.", "\u0628\u0631\u0633\u062a \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062d\u0641\u0627\u0638\u062a \u0646\u0645\u06cc\u200c\u0634\u0648\u062f (\u0628\u0631\u0633\u062a \u0645\u062d\u0627\u0641\u0638\u062a\u200c\u0646\u0645\u06cc\u200c\u0634\u0648\u062f)."],
  },
  (28, 76): {
   "topic": "imperforateHymen",
   "lead": "\u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u0627\u0648\u0644\u06cc\u0647 + \u062f\u0631\u062f \u0642\u0627\u0639\u062f\u06af\u06cc\u200c\u0647\u0627\u06cc \u0633\u06cc\u06a9\u0644\u06cc\u06a9 + \u062a\u0648\u062f\u0647\u0654 \u0622\u0628\u06cc \u0628\u0631\u062c\u0633\u062a\u0647 \u062f\u0631 \u0648\u0631\u0648\u062f\u06cc \u0648\u0627\u0698\u0646 + \u062a\u0648\u062f\u0647\u0654 \u0628\u0627\u0644\u0627\u06cc \u0639\u0627\u0646\u0647 \u062f\u0631 \u0646\u0648\u062c\u0648\u0627\u0646 \u0628\u0627 \u0628\u0644\u0648\u063a \u06a9\u0627\u0645\u0644: \u0647\u0627\u06cc\u0645\u0646 \u0628\u062f\u0648\u0646 \u0633\u0648\u0631\u0627\u062e.",
   "interpretation": "\u062f\u0631 \u0647\u0627\u06cc\u0645\u0646 \u0628\u062f\u0648\u0646 \u0633\u0648\u0631\u0627\u062e (\u0647\u0627\u06cc\u0645\u0646 \u0628\u062f\u0648\u0646 \u0633\u0648\u0631\u0627\u062e) \u062e\u0648\u0646 \u0642\u0627\u0639\u062f\u06af\u06cc \u067e\u0634\u062a \u067e\u0631\u062f\u0647 \u062c\u0645\u0639 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0647\u0645\u0627\u062a\u0648\u06a9\u0648\u0644\u067e\u0648\u0633/\u06a9\u0648\u0644\u067e\u0648\u0647\u0645\u0627\u062a\u0648\u06a9\u0644\u067e\u0648\u0633 \u062a\u0634\u06a9\u06cc\u0644 \u0645\u06cc\u200c\u062f\u0647\u062f\u061b \u0628\u0631\u062c\u0633\u062a\u06af\u06cc \u0622\u0628\u06cc\u200c\u0631\u0646\u06af \u063a\u0634\u0627\u06cc \u0647\u0627\u06cc\u0645\u0646 \u062f\u0631 \u0645\u0639\u0627\u06cc\u0646\u0647 (\u0646\u062a\u06cc\u062c\u0647\u0654 \u0641\u0634\u0627\u0631 \u062e\u0648\u0646 \u062c\u0645\u0639\u200c\u0634\u062f\u0647) \u0628\u0647\u0639\u0644\u0627\u0648\u0647\u0654 \u062a\u0648\u062f\u0647\u0654 \u0628\u0627\u0644\u0627\u06cc \u0633\u0645\u0641\u06cc\u0632 \u067e\u0648\u0628\u06cc\u0633 (\u0631\u062d\u0645/\u0648\u0627\u0698\u0646 \u0645\u062a\u0633\u0639\u200c\u0634\u062f\u0647\u0654 \u0645\u0645\u0644\u0648 \u0627\u0632 \u062e\u0648\u0646) \u0648 \u062f\u0631\u062f\u0647\u0627\u06cc \u0633\u06cc\u06a9\u0644\u06cc\u06a9 \u0628\u062f\u0648\u0646 \u0628\u06cc\u0631\u0648\u0646\u200c\u0632\u062f\u06af\u06cc\u060c \u062a\u0642\u0631\u06cc\u0628\u0627\u064b \u067e\u0627\u062a\u0648\u06af\u0646\u0648\u0645\u0648\u0646\u06cc\u06a9 \u0647\u0627\u06cc\u0645\u0646 \u0628\u062f\u0648\u0646 \u0633\u0648\u0631\u0627\u062e \u0627\u0633\u062a\u061b \u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u0647\u06cc\u067e\u0648\u062a\u0627\u0644\u0627\u0645\u0648\u0633\u06cc \u0648 PCOS \u0628\u062f\u0648\u0646 \u062a\u0648\u062f\u0647\u0654 \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0647\u0633\u062a\u0646\u062f \u0648 \u0622\u0698\u0646\u0632\u06cc \u0648\u0627\u0698\u0646 \u0628\u0644\u0648\u063a \u067e\u0633\u062a\u0627\u0646\u06cc \u062f\u0627\u0631\u062f \u0648\u0644\u06cc \u063a\u0634\u0627\u06cc \u0622\u0628\u06cc \u0628\u0631\u062c\u0633\u062a\u0647 \u0646\u062f\u0627\u0631\u062f.",
   "reasons": ["\u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u0647\u06cc\u067e\u0648\u062a\u0627\u0644\u0627\u0645\u0648\u0633\u06cc \u0628\u0627 \u0639\u0644\u0627\u06cc\u0645 \u0627\u0646\u0633\u062f\u0627\u062f\u06cc \u0648 \u062a\u0648\u062f\u0647\u0654 \u0645\u062a\u0633\u0639 \u0647\u0645\u0631\u0627\u0647 \u0646\u06cc\u0633\u062a.", "PCOS \u0628\u0627 \u0639\u062f\u0645 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0648 \u0639\u0644\u0627\u06cc\u0645 \u0622\u0646\u062f\u0631\u0648\u0698\u0646\u06cc \u0645\u06cc\u200c\u0622\u06cc\u062f \u0646\u0647 \u0628\u0627 \u0639\u0644\u0627\u06cc\u0645 \u0627\u0646\u0633\u062f\u0627\u062f\u06cc \u0648\u0627\u0698\u0646 \u0648 \u062a\u0648\u062f\u0647\u0654 \u062e\u0648\u0646\u06cc.", "\u0622\u0698\u0646\u0632\u06cc \u0645\u0648\u0644\u0631\u06cc\u0646 \u062a\u0648\u062f\u0647\u0654 \u0622\u0628\u06cc \u0628\u0631\u062c\u0633\u062a\u0647 \u062f\u0631 \u0648\u0631\u0648\u062f\u06cc \u0647\u0627\u06cc\u0645\u0646 \u0646\u062f\u0627\u0631\u062f.", "\u0647\u0627\u06cc\u0645\u0646 \u0628\u062f\u0648\u0646 \u0633\u0648\u0631\u0627\u062e \u0628\u0627 \u0627\u06cc\u0646 \u0648\u06cc\u0698\u06af\u06cc\u200c\u0647\u0627 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 77): {
   "topic": "myomaAsymptomaticObserve",
   "lead": "\u0645\u06cc\u0648\u0645 \u0633\u0627\u0628\u200c\u0633\u0631\u0648\u0632\u0627\u0644 \u06f4 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631\u06cc \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u062f\u0631 \u0632\u0646 \u06f4\u06f8 \u0633\u0627\u0644\u0647: \u0646\u06cc\u0627\u0632 \u0628\u0647 \u0627\u0642\u062f\u0627\u0645 \u062c\u0631\u0627\u062d\u06cc \u06cc\u0627 \u062f\u0627\u0631\u0648\u06cc\u06cc \u0646\u062f\u0627\u0631\u062f \u0648 \u0628\u06cc\u0645\u0627\u0631 \u062a\u062d\u062a \u0646\u0638\u0631 (\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc/\u0645\u0639\u0627\u06cc\u0646\u0647 \u062f\u0648\u0631\u0647\u200c\u0627\u06cc) \u0628\u0627\u0642\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f.",
   "interpretation": "\u062f\u0631 \u0646\u0632\u062f\u06cc\u06a9\u06cc \u06cc\u0627\u0626\u0633\u06af\u06cc \u0628\u0633\u06cc\u0627\u0631\u06cc \u0627\u0632 \u0645\u06cc\u0648\u0645\u200c\u0647\u0627 \u06a9\u0648\u0686\u06a9 \u0648 \u0633\u0627\u06a9\u0646 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f \u0648 \u0645\u06cc\u0648\u0645\u200c\u0647\u0627\u06cc \u0633\u0627\u0628\u200c\u0633\u0631\u0648\u0632\u0627\u0644 \u06a9\u0645\u200c\u062a\u0631 \u0627\u0632 \u0647\u0645\u0647 \u0628\u0647 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc/\u0641\u0634\u0627\u0631\u06cc \u0645\u06cc\u200c\u0627\u0646\u062c\u0627\u0645\u0646\u062f\u061b \u0646\u06cc\u0627\u0632 \u0628\u0647 \u062f\u0631\u0645\u0627\u0646 \u062a\u0647\u0627\u062c\u0645\u06cc \u0641\u0642\u0637 \u0628\u0627 \u0639\u0644\u0627\u06cc\u0645 (\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0634\u062f\u06cc\u062f\u060c \u062f\u0631\u062f\u060c \u0631\u0634\u062f \u0633\u0631\u06cc\u0639\u060c \u0641\u0634\u0631\u062f\u06af\u06cc \u0627\u0631\u06af\u0627\u0646\u200c\u0647\u0627 \u06cc\u0627 \u0634\u06a9 \u0628\u062f\u062e\u06cc\u0645\u06cc) \u067e\u062f\u06cc\u062f \u0645\u06cc\u200c\u0622\u06cc\u062f\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u0627\u0631\u062c\u0627\u0639 \u0628\u0647 \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u06cc\u0627 \u0645\u06cc\u0648\u0645\u06a9\u062a\u0648\u0645\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0646\u0642\u0637\u0647 \u0627\u0641\u0631\u0627\u0637 \u0627\u0633\u062a \u0648 OCP \u0628\u0631\u0627\u06cc \u0645\u06cc\u0648\u0645 \u0645\u062d\u0636 \u062f\u0631\u0645\u0627\u0646\u06cc \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0634\u06a9\u0645\u06cc \u0628\u0631\u0627\u06cc \u0645\u06cc\u0648\u0645 \u06f4 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631\u06cc \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u0627\u0641\u0631\u0627\u0637 \u0627\u0633\u062a.", "\u0646\u0638\u0627\u0631\u062a \u0648 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u062f\u0648\u0631\u0647\u200c\u0627\u06cc \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "OCP \u0641\u0642\u0637 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u062f\u0631 \u0645\u06cc\u0648\u0645 \u0639\u0644\u0627\u0645\u062a\u200c\u062f\u0627\u0631\u0650 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0646\u0642\u0634 \u062f\u0627\u0634\u062a\u0647 \u0628\u0627\u0634\u062f \u0646\u0647 \u062f\u0631 \u0645\u06cc\u0648\u0645 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u06a9\u0648\u0686\u06a9.", "\u0645\u06cc\u0648\u0645\u06a9\u062a\u0648\u0645\u06cc \u0634\u06a9\u0645\u06cc \u062f\u0631 \u0645\u06cc\u0648\u0645 \u06a9\u0648\u0686\u06a9 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u062a\u0648\u062c\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f."],
  },
}
